/*
 * Flatpack UI — theme layer
 * ---------------------------------------------------------------------------
 * The whole look in one file. Components mark their parts with data-slot;
 * this file finds them and applies the finish. Swap this file, swap the system.
 *
 * Three rules: shape by role, black and white, whitespace.
 *   - Clickable single-line parts use --fp-radius-control (pill by default; 0 in
 *     the All square preset). Surfaces that hold content use --fp-radius-surface
 *     (0 by default; a theme may set a small radius). Avatars and the radio dot
 *     are round. Layers that float above the page (dialog, menus, toast) use
 *     --fp-radius-floating (20px by default; 0 in the All square preset).
 *     No in-between radii.
 *   - One accent per theme (--fp-accent), ink by default. Red and green appear
 *     in text and icons only.
 *   - Space separates sections. One 1px line. One shadow, for floating layers.
 *
 * Everything below the token block sits in @layer base / components, so Tailwind
 * utilities in product code win over it, as with any shadcn-style component.
 *
 * The token block below is generated from tokens/flatpack.tokens.json by
 * `npm run build:tokens`. Edit the JSON, not the block.
 */

@import "tailwindcss";

@theme inline {
  --color-bg: var(--fp-bg);
  --color-surface: var(--fp-surface);
  --color-line: var(--fp-line);
  --color-line-strong: var(--fp-line-strong);
  --color-muted: var(--fp-muted);
  --color-ink: var(--fp-ink);
  --color-brand: var(--fp-accent);
  --color-on-brand: var(--fp-on-accent);
  --color-danger: var(--fp-danger);
  --color-success: var(--fp-success);
  --font-sans: var(--fp-sans);
  --font-mono: var(--fp-mono);
  --radius-*: initial;
  --shadow-*: initial;
}

/* @tokens:start */
:root {
  color-scheme: light;
  /* neutral gray scale: every color below comes from here */
  --fp-gray-0: #ffffff;
  --fp-gray-1: #fafafa;
  --fp-gray-2: #f5f5f5;
  --fp-gray-3: #e5e5e5;
  --fp-gray-4: #a3a3a3;
  --fp-gray-5: #6b6b6b;
  --fp-gray-6: #525252;
  --fp-gray-7: #262626;
  --fp-gray-8: #0a0a0a;
  --fp-gray-9: #000000;

  --fp-bg: var(--fp-gray-0);             /* Page background */
  --fp-surface: var(--fp-gray-2);        /* Raised surface, image placeholder */
  --fp-line: var(--fp-gray-3);           /* The only line color */
  --fp-line-strong: var(--fp-gray-4);    /* Inputs and hover borders */
  --fp-muted: var(--fp-gray-5);          /* Secondary text (the only one) */
  --fp-ink: var(--fp-gray-8);            /* Text and strong borders */
  --fp-accent: var(--fp-ink);            /* Primary button, selected and active states, focus ring. Ink by default; a theme may set its brand color */
  --fp-on-accent: var(--fp-bg);          /* Text and icons on the accent color */
  --fp-danger: #c62828;                  /* Error, text and icons only */
  --fp-success: #2e7d32;                 /* Success, text and icons only */
  --fp-scrim: rgba(0, 0, 0, 0.4);        /* Overlay behind dialogs */
  --fp-shadow-pop: 0 8px 24px rgba(0, 0, 0, 0.12);

  --fp-text-xs: 12px;
  --fp-text-sm: 14px;
  --fp-text-base: 16px;
  --fp-text-lg: 20px;
  --fp-text-xl: 28px;
  --fp-text-2xl: 40px;
  --fp-text-3xl: 64px;
  --fp-text-4xl: 96px;
  --fp-leading-body: 1.6;
  --fp-leading-heading: 1.1;
  --fp-weight-regular: 400;
  --fp-weight-medium: 500;
  --fp-weight-semibold: 600;
  --fp-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Hiragino Sans GB", "Microsoft YaHei", ui-sans-serif, system-ui, sans-serif;
  --fp-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --fp-tracking-display: -0.02em;

  --fp-space-1: 4px;
  --fp-space-2: 8px;
  --fp-space-3: 12px;
  --fp-space-4: 16px;
  --fp-space-5: 24px;
  --fp-space-6: 32px;
  --fp-space-7: 48px;
  --fp-space-8: 64px;
  --fp-space-9: 96px;
  --fp-space-10: 128px;
  --fp-border: 1px;
  --fp-radius-control: 9999px;           /* Clickable single-line parts */
  --fp-radius-surface: 0;                /* Surfaces that hold content. 0 by default; a theme may set a small radius */
  --fp-radius-floating: 20px;            /* Layers that float above the page (dialog, menus, toast) and multi-line fields (Textarea, Composer, multi-select). 20px by default; 0 in the Square preset */
  --fp-control-sm: 32px;
  --fp-control-md: 40px;
  --fp-control-lg: 48px;
  --fp-icon: 16px;
  --fp-page-max: 1280px;                 /* Page container max width: shared by header, pages and footer so their edges line up */
  --fp-duration: 150ms;
  --fp-ease: ease;
  --fp-reveal-duration: 240ms;
  --fp-reveal-step: 40ms;
  --fp-reveal-distance: 0px;
  --fp-reveal-ease: cubic-bezier(0.2, 0.75, 0.2, 1);
  --fp-reveal-duration-sm: 240ms;
  --fp-reveal-distance-sm: 0px;
}

[data-theme="dark"] {
  color-scheme: dark;
  --fp-bg: var(--fp-gray-9);
  --fp-surface: var(--fp-gray-8);
  --fp-line: var(--fp-gray-7);
  --fp-line-strong: var(--fp-gray-6);
  --fp-muted: var(--fp-gray-4);
  --fp-ink: var(--fp-gray-1);
  --fp-accent: var(--fp-ink);
  --fp-on-accent: var(--fp-bg);
  --fp-danger: #ef5350;
  --fp-success: #66bb6a;
  --fp-scrim: rgba(0, 0, 0, 0.7);
  --fp-shadow-pop: 0 8px 24px rgba(0, 0, 0, 0.6);
}

:root:not([data-theme="dark"]) .fp-invert {
  --fp-bg: var(--fp-gray-9);
  --fp-surface: var(--fp-gray-8);
  --fp-line: var(--fp-gray-7);
  --fp-line-strong: var(--fp-gray-6);
  --fp-muted: var(--fp-gray-4);
  --fp-ink: var(--fp-gray-1);
  --fp-accent: var(--fp-ink);
  --fp-on-accent: var(--fp-bg);
  --fp-danger: #ef5350;
  --fp-success: #66bb6a;
  --fp-scrim: rgba(0, 0, 0, 0.7);
  background: var(--fp-bg);
  color: var(--fp-ink);
}
[data-theme="dark"] .fp-invert {
  --fp-bg: var(--fp-gray-0);
  --fp-surface: var(--fp-gray-2);
  --fp-line: var(--fp-gray-3);
  --fp-line-strong: var(--fp-gray-4);
  --fp-muted: var(--fp-gray-5);
  --fp-ink: var(--fp-gray-8);
  --fp-accent: var(--fp-ink);
  --fp-on-accent: var(--fp-bg);
  --fp-danger: #c62828;
  --fp-success: #2e7d32;
  --fp-scrim: rgba(0, 0, 0, 0.4);
  background: var(--fp-bg);
  color: var(--fp-ink);
}

/* tune dials (Create page): set data-fp-<dial> on any element */
[data-fp-density="compact"] {
  --fp-space-1: 4px;
  --fp-space-2: 6px;
  --fp-space-3: 8px;
  --fp-space-4: 12px;
  --fp-space-5: 16px;
  --fp-space-6: 24px;
  --fp-space-7: 32px;
  --fp-space-8: 48px;
  --fp-space-9: 64px;
  --fp-space-10: 96px;
  --fp-control-sm: 28px;
  --fp-control-md: 32px;
  --fp-control-lg: 40px;
}
[data-fp-density="roomy"] {
  --fp-space-1: 4px;
  --fp-space-2: 8px;
  --fp-space-3: 16px;
  --fp-space-4: 20px;
  --fp-space-5: 32px;
  --fp-space-6: 40px;
  --fp-space-7: 64px;
  --fp-space-8: 80px;
  --fp-space-9: 128px;
  --fp-space-10: 160px;
  --fp-control-sm: 36px;
  --fp-control-md: 44px;
  --fp-control-lg: 56px;
}
[data-fp-font="noto"] {
  --fp-sans: "Noto Sans SC", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Hiragino Sans GB", "Microsoft YaHei", ui-sans-serif, system-ui, sans-serif;
}
[data-fp-font="inter"] {
  --fp-sans: "Inter", "Noto Sans SC", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Noto Sans SC", "Hiragino Sans GB", "Microsoft YaHei", ui-sans-serif, system-ui, sans-serif;
}
[data-fp-heading="serif"] {
  --fp-heading: "Noto Serif SC", "Songti SC", "STSong", serif;
}
[data-fp-body="15"] {
  --fp-text-base: 15px;
}
[data-fp-weight="500"] {
  --fp-weight-semibold: 500;
}
[data-fp-tracking="-0.03em"] {
  --fp-tracking-display: -0.03em;
}
[data-fp-tracking="0em"] {
  --fp-tracking-display: 0em;
}
[data-fp-gray="warm"] {
  --fp-gray-0: #ffffff;
  --fp-gray-1: #fafaf9;
  --fp-gray-2: #f5f5f4;
  --fp-gray-3: #e7e5e4;
  --fp-gray-4: #a8a29e;
  --fp-gray-5: #78716c;
  --fp-gray-6: #57534e;
  --fp-gray-7: #292524;
  --fp-gray-8: #0c0a09;
  --fp-gray-9: #000000;
  --fp-bg: var(--fp-gray-0);
  --fp-surface: var(--fp-gray-2);
  --fp-line: var(--fp-gray-3);
  --fp-line-strong: var(--fp-gray-4);
  --fp-muted: var(--fp-gray-5);
  --fp-ink: var(--fp-gray-8);
  --fp-accent: var(--fp-ink);
  --fp-on-accent: var(--fp-bg);
  --fp-danger: #c62828;
  --fp-success: #2e7d32;
  --fp-scrim: rgba(0, 0, 0, 0.4);
}
[data-theme="dark"] [data-fp-gray="warm"], [data-theme="dark"][data-fp-gray="warm"] {
  --fp-bg: var(--fp-gray-9);
  --fp-surface: var(--fp-gray-8);
  --fp-line: var(--fp-gray-7);
  --fp-line-strong: var(--fp-gray-6);
  --fp-muted: var(--fp-gray-4);
  --fp-ink: var(--fp-gray-1);
  --fp-accent: var(--fp-ink);
  --fp-on-accent: var(--fp-bg);
  --fp-danger: #ef5350;
  --fp-success: #66bb6a;
  --fp-scrim: rgba(0, 0, 0, 0.7);
}
[data-fp-shape="square"] {
  --fp-radius-control: 0;
  --fp-radius-floating: 0;
}
[data-fp-theme="catalog"] {
  --fp-bg: #ffffff;
  --fp-surface: #f5f5f5;
  --fp-line: #e3e3e3;
  --fp-line-strong: #c4c4c4;
  --fp-muted: #626262;
  --fp-ink: #111111;
  --fp-accent: #111111;
  --fp-on-accent: #ffffff;
  --fp-danger: #ad2828;
  --fp-success: #2e7d32;
  --fp-scrim: rgba(0, 0, 0, 0.4);
  --fp-radius-surface: 4px;
  --fp-radius-floating: 8px;
  --fp-sans: Arial, "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  --fp-reveal-duration: 480ms;
  --fp-reveal-step: 50ms;
  --fp-reveal-distance: 10px;
  --fp-reveal-duration-sm: 400ms;
  --fp-reveal-distance-sm: 6px;
}
[data-theme="dark"] [data-fp-theme="catalog"], [data-theme="dark"][data-fp-theme="catalog"] {
  --fp-bg: #121212;
  --fp-surface: #242424;
  --fp-line: #383838;
  --fp-line-strong: #5a5a5a;
  --fp-muted: #b3b3b3;
  --fp-ink: #f5f5f5;
  --fp-accent: #f5f5f5;
  --fp-on-accent: #121212;
  --fp-danger: #ff9b9b;
  --fp-success: #66bb6a;
  --fp-scrim: rgba(0, 0, 0, 0.7);
}
[data-fp-theme="sage"] {
  --fp-bg: #f8f9f7;
  --fp-surface: #f0f2ee;
  --fp-line: #e1e6df;
  --fp-line-strong: #c3ccc1;
  --fp-muted: #656f66;
  --fp-ink: #202722;
  --fp-accent: #236b4b;
  --fp-on-accent: #ffffff;
  --fp-danger: #c3453d;
  --fp-success: #2e7d32;
  --fp-scrim: rgba(20, 26, 22, 0.4);
  --fp-radius-control: 10px;
  --fp-radius-surface: 10px;
  --fp-radius-floating: 16px;
  --fp-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  --fp-reveal-duration: 560ms;
  --fp-reveal-step: 70ms;
  --fp-reveal-distance: 14px;
  --fp-reveal-duration-sm: 440ms;
  --fp-reveal-distance-sm: 8px;
}
[data-theme="dark"] [data-fp-theme="sage"], [data-theme="dark"][data-fp-theme="sage"] {
  --fp-bg: #141a16;
  --fp-surface: #1b231d;
  --fp-line: #323d33;
  --fp-line-strong: #4c5a4d;
  --fp-muted: #a1ada0;
  --fp-ink: #edf0ea;
  --fp-accent: #a6d4aa;
  --fp-on-accent: #16271b;
  --fp-danger: #f38c85;
  --fp-success: #66bb6a;
  --fp-scrim: rgba(0, 0, 0, 0.7);
}
/* @tokens:end */

@layer base {
/* ==========================================================================
 * Base
 * ========================================================================== */
* { box-sizing: border-box; }
html { background: var(--fp-bg); }
body {
  margin: 0;
  background: var(--fp-bg);
  color: var(--fp-ink);
  font-family: var(--fp-sans);
  font-size: var(--fp-text-base);
  font-weight: var(--fp-weight-regular);
  line-height: var(--fp-leading-body);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { font-family: var(--fp-heading, var(--fp-sans)); font-weight: var(--fp-weight-semibold); line-height: var(--fp-leading-heading); margin: 0; }
p { margin: 0; }
button, input, textarea, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--fp-ink); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
code, kbd, pre, samp { font-family: var(--fp-mono); }
:focus-visible { outline: 2px solid var(--fp-accent); outline-offset: 2px; }
::selection { background: var(--fp-accent); color: var(--fp-on-accent); }
svg.lucide { stroke-width: 1.5; }
}

@layer components {
/* One page container for header, pages and footer, so every left and right edge lines up. */
.fp-container { width: 100%; max-width: calc(var(--fp-page-max) + 2 * var(--fp-space-6)); margin-inline: auto; padding-inline: var(--fp-space-6); }
.fp-page-pad { padding: 0 var(--fp-space-6); }
@media (max-width: 720px) {
  .fp-page-pad { padding: 0 var(--fp-space-4); }
  .fp-container { padding-inline: var(--fp-space-4); }
}

/* Utilities ---------------------------------------------------------------- */
/* Small grey caption. Sans, sentence case: Chinese has no letter case. */
.fp-label {
  font-size: var(--fp-text-xs);
  font-weight: var(--fp-weight-medium);
  line-height: var(--fp-leading-body);
  color: var(--fp-muted);
}
/* Numbers, IDs, code: the only place for the monospace face. */
.fp-num { font-family: var(--fp-mono); font-variant-numeric: tabular-nums; }
.fp-muted { color: var(--fp-muted); }

/* ==========================================================================
 * data-slot hooks — components only supply structure + these attributes
 * ========================================================================== */

/* ---- button -------------------------------------------------------------- */
[data-slot="button"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--fp-space-2);
  height: var(--fp-control-md);
  padding: 0 var(--fp-space-4);
  border: 1px solid transparent;
  border-radius: var(--fp-radius-control);
  background: transparent;
  font-size: var(--fp-text-sm);
  font-weight: var(--fp-weight-medium);
  line-height: 1;
  white-space: nowrap;
  text-decoration: none;
  transition: background-color var(--fp-duration) var(--fp-ease),
              border-color var(--fp-duration) var(--fp-ease),
              color var(--fp-duration) var(--fp-ease);
}
[data-slot="button"][data-variant="default"] {
  background: var(--fp-accent);
  color: var(--fp-on-accent);
  border-color: var(--fp-accent);
}
[data-slot="button"][data-variant="default"]:hover { background: transparent; color: var(--fp-accent); }
/* Outline: an ink ring, the secondary action next to a primary one. */
[data-slot="button"][data-variant="outline"] { color: var(--fp-ink); border-color: var(--fp-ink); }
[data-slot="button"][data-variant="outline"]:hover { background: var(--fp-surface); }
/* Secondary: a quieter grey ring that turns ink on hover. */
[data-slot="button"][data-variant="secondary"] { color: var(--fp-ink); border-color: var(--fp-line-strong); }
[data-slot="button"][data-variant="secondary"]:hover { border-color: var(--fp-ink); }
/* Destructive: red text and ring only. Red never fills a surface. */
[data-slot="button"][data-variant="destructive"] { color: var(--fp-danger); border-color: var(--fp-danger); }
[data-slot="button"][data-variant="destructive"]:hover { background: var(--fp-surface); }
[data-slot="button"][data-variant="ghost"] { color: var(--fp-ink); }
[data-slot="button"][data-variant="ghost"]:hover { background: var(--fp-surface); }
[data-slot="button"][data-variant="link"] {
  color: var(--fp-ink);
  border: 0;
  height: auto;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
}
[data-slot="button"][data-size="sm"] { height: var(--fp-control-sm); padding: 0 var(--fp-space-3); }
[data-slot="button"][data-size="lg"] { height: var(--fp-control-lg); padding: 0 var(--fp-space-5); }
[data-slot="button"][data-size="icon"] { width: var(--fp-control-md); padding: 0; }
[data-slot="button"][data-size="icon-sm"] { width: var(--fp-control-sm); height: var(--fp-control-sm); padding: 0; }
[data-slot="button"][data-size="icon-lg"] { width: var(--fp-control-lg); height: var(--fp-control-lg); padding: 0; }
[data-slot="button"]:disabled { opacity: 0.4; pointer-events: none; }

/* ---- card ---------------------------------------------------------------- */
/* One border. Nothing inside a card draws a second frame. */
[data-slot="card"] {
  background: var(--fp-bg);
  border: 1px solid var(--fp-line);
  border-radius: var(--fp-radius-surface);
  overflow: hidden;
}
[data-slot="card-header"]:has([data-slot="card-action"]) { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: var(--fp-space-3); }
[data-slot="card-action"] { grid-column: 2; grid-row: 1 / span 2; align-self: start; justify-self: end; }
[data-slot="card-header"] { display: flex; flex-direction: column; gap: var(--fp-space-1); padding: var(--fp-space-5) var(--fp-space-5) 0; }
[data-slot="card-title"] { font-size: var(--fp-text-base); font-weight: var(--fp-weight-semibold); margin: 0; }
[data-slot="card-description"] { font-size: var(--fp-text-sm); color: var(--fp-muted); margin: 0; }
[data-slot="card-content"] { padding: var(--fp-space-5); }
[data-slot="card-footer"] { display: flex; align-items: center; gap: var(--fp-space-2); padding: 0 var(--fp-space-5) var(--fp-space-5); }

/* ---- badge --------------------------------------------------------------- */
[data-slot="badge"] {
  display: inline-flex;
  align-items: center;
  gap: var(--fp-space-1);
  height: 24px;
  padding: 0 var(--fp-space-2);
  border: 1px solid transparent;
  border-radius: var(--fp-radius-control);
  font-size: var(--fp-text-xs);
  font-weight: var(--fp-weight-medium);
  line-height: 1;
  white-space: nowrap;
}
[data-slot="badge"][data-variant="default"] { background: var(--fp-accent); color: var(--fp-on-accent); }
[data-slot="badge"][data-variant="secondary"] { background: var(--fp-surface); color: var(--fp-ink); }
[data-slot="badge"][data-variant="outline"] { border-color: var(--fp-line-strong); color: var(--fp-ink); }
[data-slot="badge"][data-variant="success"] { border-color: var(--fp-line-strong); color: var(--fp-success); }
[data-slot="badge"][data-variant="danger"]  { border-color: var(--fp-line-strong); color: var(--fp-danger); }

/* ---- input --------------------------------------------------------------- */
[data-slot="input"] {
  width: 100%;
  height: var(--fp-control-md);
  padding: 0 var(--fp-space-3);
  background: transparent;
  border: 1px solid var(--fp-line-strong);
  border-radius: var(--fp-radius-control);
  font-size: var(--fp-text-sm);
  outline: none;
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="input"]:hover { border-color: var(--fp-muted); }
[data-slot="input"]::placeholder { color: var(--fp-muted); }
[data-slot="input"]:focus { border-color: var(--fp-accent); }
[data-slot="label"] { display: block; font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); margin-bottom: var(--fp-space-2); }

/* ---- floating layers: the only place a shadow appears ------------------- */
[data-slot="dialog-content"],
[data-slot="popover-content"],
[data-slot="select-content"],
[data-slot="dropdown-content"] {
  background: var(--fp-bg);
  border: 1px solid var(--fp-line);
  border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}

/* ---- dialog -------------------------------------------------------------- */
[data-slot="dialog-overlay"], [data-slot="sheet-overlay"] {
  position: fixed; inset: 0; z-index: 50;
  background: var(--fp-scrim);
}
[data-slot="dialog-content"] {
  position: fixed; z-index: 51;
  left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(480px, calc(100vw - 32px));
  max-height: calc(100vh - 32px); overflow-y: auto;
  padding: var(--fp-space-6);
}
[data-slot="dialog-header"] { display: flex; flex-direction: column; gap: var(--fp-space-2); margin-bottom: var(--fp-space-5); }
[data-slot="dialog-title"] { font-size: var(--fp-text-lg); font-weight: var(--fp-weight-semibold); margin: 0; }
[data-slot="dialog-description"] { font-size: var(--fp-text-sm); color: var(--fp-muted); margin: 0; }
[data-slot="dialog-footer"] { display: flex; justify-content: flex-end; gap: var(--fp-space-2); margin-top: var(--fp-space-5); }

/* ---- tabs ---------------------------------------------------------------- */
[data-slot="tabs"] { display: flex; flex-direction: column; gap: var(--fp-space-4); }
[data-slot="tabs-list"] {
  display: flex;
  gap: var(--fp-space-5);
  border-bottom: 1px solid var(--fp-line);
}
[data-slot="tabs-trigger"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-2);
  height: var(--fp-control-md); padding: 0;
  margin-bottom: -1px;
  border: 0; border-bottom: 1px solid transparent; border-radius: 0;
  background: transparent;
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium);
  color: var(--fp-muted);
  transition: color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="tabs-trigger"]:hover { color: var(--fp-ink); }
[data-slot="tabs-trigger"][data-active]:not([data-active="false"]) { color: var(--fp-ink); border-bottom-color: var(--fp-accent); }
[data-slot="tabs-content"] { font-size: var(--fp-text-sm); color: var(--fp-muted); }
[data-slot="tabs-content"][hidden] { display: none; }

/* ---- sheet --------------------------------------------------------------- */
[data-slot="sheet-content"] {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 51;
  width: min(400px, 90vw);
  background: var(--fp-bg);
  border-left: 1px solid var(--fp-line);
  box-shadow: var(--fp-shadow-pop);
  padding: var(--fp-space-6);
  overflow-y: auto;
}
[data-slot="sheet-title"] { font-size: var(--fp-text-lg); font-weight: var(--fp-weight-semibold); margin: 0 0 var(--fp-space-5); }

/* ---- dropdown ------------------------------------------------------------ */
[data-slot="dropdown"] { position: relative; display: inline-block; }
/* Base UI positions popups through a Positioner; keep every one above dialogs and sheets. */
[data-slot$="-positioner"] { z-index: 60; }
[data-slot="dropdown-content"] {
  min-width: 200px;
  padding: var(--fp-space-1);
}
[data-slot="dropdown-content"][hidden] { display: none; }
[data-slot="dropdown-item"], [data-slot="select-item"] {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  border: 0; border-radius: var(--fp-radius-control); background: transparent;
  font-size: var(--fp-text-sm); text-align: left;
  transition: background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="dropdown-item"]:hover, [data-slot="select-item"]:hover,
[data-slot="dropdown-item"][data-highlighted], [data-slot="select-item"][data-highlighted] { background: var(--fp-surface); }
[data-slot="dropdown-item"][data-destructive] { color: var(--fp-danger); }
[data-slot="dropdown-item"][data-disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="dropdown-separator"] { height: 1px; background: var(--fp-line); margin: var(--fp-space-1) 0; }

/* ---- sidebar ------------------------------------------------------------- */
[data-slot="sidebar"] {
  width: 224px; flex-shrink: 0;
  background: var(--fp-bg);
  border-right: 1px solid var(--fp-line);
  display: flex; flex-direction: column;
}
[data-slot="sidebar-section"] { padding: var(--fp-space-4) var(--fp-space-3) var(--fp-space-1); }
[data-slot="sidebar-section"] > .fp-label { padding: 0 var(--fp-space-3) var(--fp-space-1); }
[data-slot="sidebar-item"] {
  display: flex; align-items: center; gap: var(--fp-space-3);
  height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  border: 0; border-radius: var(--fp-radius-control);
  background: transparent; color: var(--fp-muted);
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); text-align: left; text-decoration: none; width: 100%;
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease);
}
[data-slot="sidebar-item"]:hover { color: var(--fp-ink); }
[data-slot="sidebar-item"][data-active="true"] { background: var(--fp-accent); color: var(--fp-on-accent); }

/* ---- table --------------------------------------------------------------- */
[data-slot="table"] { width: 100%; border-collapse: collapse; font-size: var(--fp-text-sm); }
[data-slot="table-header"] { border-bottom: 1px solid var(--fp-line); }
[data-slot="table-head"] {
  padding: var(--fp-space-3) var(--fp-space-4); text-align: left;
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium);
  color: var(--fp-muted);
}
[data-slot="table-body"] [data-slot="table-row"] { border-bottom: 1px solid var(--fp-line); }
[data-slot="table-body"] [data-slot="table-row"]:hover { background: var(--fp-surface); }
[data-slot="table-cell"] { padding: var(--fp-space-3) var(--fp-space-4); }
[data-slot="table-container"] { position: relative; width: 100%; max-width: 100%; min-width: 0; overflow-x: auto; }
[data-slot="table-caption"] { padding: var(--fp-space-3) var(--fp-space-4); font-size: var(--fp-text-sm); color: var(--fp-muted); text-align: left; caption-side: top; }

/* ---- data table ---------------------------------------------------------- */
[data-slot="data-table"] { display: flex; flex-direction: column; gap: var(--fp-space-4); min-width: 0; }
[data-slot="table-head"][data-align="end"], [data-slot="table-cell"][data-align="end"] { text-align: right; font-variant-numeric: tabular-nums; }
[data-slot="data-table"] [data-select="true"] { width: 1%; padding-right: 0; }
[data-slot="data-table-sort"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-1);
  margin: 0; padding: 0; border: 0; background: transparent;
  font: inherit; color: inherit; cursor: pointer;
  transition: color var(--fp-duration) var(--fp-ease);
}
[data-align="end"] > [data-slot="data-table-sort"] { flex-direction: row-reverse; }
[data-slot="data-table-sort"]:hover, [data-slot="data-table-sort"][data-active="true"] { color: var(--fp-ink); }
[data-slot="data-table-sort-icon"] { display: inline-flex; color: var(--fp-muted); }
[data-slot="data-table-sort"][data-active="true"] [data-slot="data-table-sort-icon"] { color: var(--fp-ink); }
[data-slot="table-body"] [data-slot="table-row"][data-selected="true"] { background: var(--fp-surface); }
[data-slot="data-table"] [data-empty="true"]:hover { background: transparent; }
[data-slot="data-table-footer"] { display: flex; justify-content: flex-end; }

/* ---- breadcrumb ---------------------------------------------------------- */
[data-slot="breadcrumb-list"] {
  display: flex; align-items: center; flex-wrap: wrap;
  gap: var(--fp-space-2); margin: 0; padding: 0; list-style: none;
}
[data-slot="breadcrumb-item"] { display: inline-flex; align-items: center; gap: var(--fp-space-2); }
[data-slot="breadcrumb-link"] { color: var(--fp-muted); font-size: var(--fp-text-sm); text-decoration: none; }
[data-slot="breadcrumb-link"]:hover { color: var(--fp-ink); text-decoration: underline; }
[data-slot="breadcrumb-current"] { color: var(--fp-ink); font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); }
[data-slot="breadcrumb-separator"] { color: var(--fp-muted); flex-shrink: 0; }

/* ---- image / photo ------------------------------------------------------- */
/* Placeholder is a quiet neutral block with no text, so it never reads as a broken image. */
[data-slot="image"], [data-slot="photo"] {
  position: relative; overflow: hidden; display: block;
  background: var(--fp-surface);
  border-radius: var(--fp-radius-surface);
  width: 100%;
}
[data-slot="image"][data-ratio="square"] { aspect-ratio: 1; }
[data-slot="image"][data-ratio="4:3"] { aspect-ratio: 4 / 3; }
[data-slot="image"][data-ratio="16:9"] { aspect-ratio: 16 / 9; }
[data-slot="image"][data-ratio="3:4"] { aspect-ratio: 3 / 4; }
[data-slot="image-element"] { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-slot="image-fallback"] { position: absolute; inset: 0; background: var(--fp-surface); }

/* ---- avatar (round: a recognised control shape) ------------------------- */
[data-slot="avatar"] {
  display: inline-grid; place-items: center; flex-shrink: 0;
  border-radius: 50%; overflow: hidden;
  background: var(--fp-line); color: var(--fp-ink);
  font-weight: var(--fp-weight-medium); font-size: var(--fp-text-xs);
  width: 32px; height: 32px;
}
[data-slot="avatar"][data-size="sm"] { width: 24px; height: 24px; }
[data-slot="avatar"][data-size="lg"] { width: 48px; height: 48px; font-size: var(--fp-text-base); }
[data-slot="avatar-image"] { width: 100%; height: 100%; object-fit: cover; }

/* ---- empty --------------------------------------------------------------- */
[data-slot="empty"] {
  display: flex; flex-direction: column; align-items: center;
  text-align: center; padding: var(--fp-space-7) var(--fp-space-5); gap: var(--fp-space-2);
}
[data-slot="empty-graphic"] { color: var(--fp-muted); margin-bottom: var(--fp-space-2); }
[data-slot="empty-title"] { font-size: var(--fp-text-base); font-weight: var(--fp-weight-semibold); color: var(--fp-ink); }
[data-slot="empty-description"] { font-size: var(--fp-text-sm); color: var(--fp-muted); max-width: 320px; }
[data-slot="empty-action"] { margin-top: var(--fp-space-4); }

/* ---- steps --------------------------------------------------------------- */
[data-slot="steps"] { display: flex; flex-direction: column; }
[data-slot="step"] { position: relative; display: flex; gap: var(--fp-space-3); padding-bottom: var(--fp-space-5); }
[data-slot="step"]:last-child { padding-bottom: 0; }
[data-slot="step-indicator"] {
  flex-shrink: 0; width: 24px; height: 24px; border-radius: var(--fp-radius-surface);
  display: grid; place-items: center;
  font-family: var(--fp-mono); font-size: var(--fp-text-xs);
  border: 1px solid var(--fp-line-strong); color: var(--fp-muted);
  background: var(--fp-bg);
}
[data-slot="step"][data-state="done"] [data-slot="step-indicator"] { background: var(--fp-accent); color: var(--fp-on-accent); border-color: var(--fp-accent); }
[data-slot="step"][data-state="current"] [data-slot="step-indicator"] { border-color: var(--fp-accent); color: var(--fp-ink); }
[data-slot="step-body"] { display: flex; flex-direction: column; gap: var(--fp-space-1); padding-top: 2px; }
[data-slot="step-title"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); line-height: 1.4; color: var(--fp-muted); }
[data-slot="step"][data-state="done"] [data-slot="step-title"],
[data-slot="step"][data-state="current"] [data-slot="step-title"] { color: var(--fp-ink); }
[data-slot="step-description"] { font-size: var(--fp-text-sm); color: var(--fp-muted); line-height: 1.4; }
[data-slot="step-track"] { position: absolute; left: 12px; top: 28px; bottom: 4px; width: 1px; background: var(--fp-line); }

/* ---- select -------------------------------------------------------------- */
[data-slot="select"] { position: relative; display: inline-block; min-width: min(200px, 100%); max-width: 100%; }
[data-slot="select-trigger"] {
  display: flex; align-items: center; justify-content: space-between; gap: var(--fp-space-2);
  width: 100%; height: var(--fp-control-md); padding: 0 var(--fp-space-3);
  background: transparent;
  border: 1px solid var(--fp-line-strong);
  border-radius: var(--fp-radius-control);
  font-size: var(--fp-text-sm); text-align: left;
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="select-trigger"]:hover { border-color: var(--fp-muted); }
[data-slot="select-trigger"][aria-expanded="true"] { border-color: var(--fp-accent); }
[data-slot="select-trigger"][disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="select-trigger"] [data-placeholder="true"], [data-slot="select-trigger"][data-placeholder] { color: var(--fp-muted); }
[data-slot="select-icon"] { color: var(--fp-muted); flex-shrink: 0; }
[data-slot="select-content"] {
  min-width: var(--anchor-width);
  padding: var(--fp-space-1);
  max-height: 240px; overflow-y: auto;
}
[data-slot="select-content"][hidden] { display: none; }
[data-slot="select-item"][data-selected]:not([data-selected="false"]) { font-weight: var(--fp-weight-medium); }
[data-slot="select-item-check"] { color: var(--fp-ink); }

/* ---- checkbox / radio / switch ------------------------------------------ */
[data-slot="checkbox"], [data-slot="radio"], [data-slot="switch"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-2);
  font-size: var(--fp-text-sm); cursor: pointer; user-select: none;
}
[data-slot="checkbox"][data-disabled="true"], [data-slot="radio"][data-disabled="true"], [data-slot="switch"][data-disabled="true"] { opacity: 0.4; pointer-events: none; }
[data-slot="checkbox"] input, [data-slot="radio"] input { position: absolute; opacity: 0; width: 0; height: 0; }
[data-slot="checkbox-box"] {
  flex-shrink: 0; width: 16px; height: 16px;
  display: grid; place-items: center;
  border: 1px solid var(--fp-line-strong);
  border-radius: 0; background: transparent;
  color: var(--fp-on-accent);
  transition: background-color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="checkbox-box"][data-disabled], [data-slot="switch-track"][data-disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="checkbox-box"][aria-invalid="true"] { border-color: var(--fp-danger); }
[data-slot="checkbox-box"][data-state="checked"], [data-slot="checkbox-box"][data-state="indeterminate"] {
  background: var(--fp-accent); border-color: var(--fp-accent);
}
[data-slot="radio-group"] { display: flex; flex-direction: column; gap: var(--fp-space-3); }
[data-slot="radio-circle"] {
  flex-shrink: 0; width: 16px; height: 16px;
  display: grid; place-items: center;
  border: 1px solid var(--fp-line-strong); border-radius: 50%;
  background: transparent;
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="radio-circle"][data-state="checked"] { border-color: var(--fp-accent); }
[data-slot="radio-dot"] { width: 8px; height: 8px; border-radius: 50%; background: var(--fp-accent); }

/* Switch: square track, square thumb. The thumb jumps; only color animates. */
[data-slot="switch-track"] {
  position: relative; flex-shrink: 0;
  width: 36px; height: 20px; padding: 0;
  border: 1px solid var(--fp-line-strong);
  border-radius: var(--fp-radius-control); background: transparent;
  transition: background-color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="switch-track"][data-state="checked"] { background: var(--fp-accent); border-color: var(--fp-accent); }
[data-slot="switch-thumb"] {
  position: absolute; top: 2px; left: 2px;
  width: 14px; height: 14px; border-radius: var(--fp-radius-control);
  background: var(--fp-line-strong);
  transition: background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="switch-track"][data-state="checked"] [data-slot="switch-thumb"] { left: 18px; background: var(--fp-on-accent); }

/* ---- alert --------------------------------------------------------------- */
[data-slot="alert"] {
  display: flex; align-items: flex-start; gap: var(--fp-space-3);
  padding: var(--fp-space-4);
  border: 1px solid var(--fp-line);
  border-radius: var(--fp-radius-surface);
  font-size: var(--fp-text-sm); line-height: 1.5;
}
[data-slot="alert-icon"] { flex-shrink: 0; color: var(--fp-ink); margin-top: 2px; }
[data-slot="alert-body"] { flex: 1; display: flex; flex-direction: column; gap: var(--fp-space-1); }
[data-slot="alert-title"] { font-weight: var(--fp-weight-semibold); color: var(--fp-ink); }
[data-slot="alert-description"] { color: var(--fp-muted); }
[data-slot="alert-close"] { flex-shrink: 0; border: 0; background: transparent; color: var(--fp-muted); padding: 0; line-height: 0; }
[data-slot="alert-close"]:hover { color: var(--fp-ink); }
[data-slot="alert"][data-variant="info"] [data-slot="alert-icon"] { color: var(--fp-muted); }
[data-slot="alert"][data-variant="success"] [data-slot="alert-icon"] { color: var(--fp-success); }
[data-slot="alert"][data-variant="error"] [data-slot="alert-icon"] { color: var(--fp-danger); }

/* ---- skeleton (static: no looping animation) ---------------------------- */
[data-slot="skeleton"] { display: block; background: var(--fp-surface); border-radius: var(--fp-radius-surface); }
[data-slot="skeleton"][data-circle="true"] { border-radius: 50%; }
[data-slot="skeleton-text"] { display: flex; flex-direction: column; gap: var(--fp-space-2); }

/* ---- tooltip ------------------------------------------------------------- */
[data-slot="tooltip"] { position: relative; display: inline-flex; }
[data-slot="tooltip-content"] {
  z-index: 50;
  padding: var(--fp-space-1) var(--fp-space-3);
  background: var(--fp-ink); color: var(--fp-bg);
  /* A pill for one line; a wrapped tooltip keeps a soft corner instead of becoming an oval. */
  border-radius: min(var(--fp-radius-control), var(--fp-space-3));
  font-size: var(--fp-text-xs);
  white-space: nowrap;
  pointer-events: none;
}
[data-slot="tooltip-content"][hidden] { display: none; }

/* ---- progress ------------------------------------------------------------ */
[data-slot="progress"] { display: flex; flex-direction: column; gap: var(--fp-space-2); width: 100%; }
[data-slot="progress-header"] { display: flex; justify-content: space-between; align-items: baseline; }
[data-slot="progress-label"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); }
[data-slot="progress-value"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="progress-track"] { width: 100%; height: 4px; overflow: hidden; background: var(--fp-line); border-radius: var(--fp-radius-surface); }
[data-slot="progress"][data-size="sm"] [data-slot="progress-track"] { height: 2px; }
[data-slot="progress"][data-size="lg"] [data-slot="progress-track"] { height: 8px; }
[data-slot="progress-bar"] { height: 100%; background: var(--fp-accent); border-radius: var(--fp-radius-surface); }

/* ---- popover ------------------------------------------------------------- */
[data-slot="popover"] { position: relative; display: inline-block; }
[data-slot="popover-content"] { position: absolute; left: 0; z-index: 45; min-width: 240px; padding: var(--fp-space-4); }
[data-slot="popover-content"][data-side="bottom"] { top: calc(100% + var(--fp-space-2)); }
[data-slot="popover-content"][data-side="top"] { bottom: calc(100% + var(--fp-space-2)); }
[data-slot="popover-title"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-semibold); margin-bottom: var(--fp-space-1); }
[data-slot="popover-body"] { font-size: var(--fp-text-sm); color: var(--fp-muted); }

/* ---- segmented: the active item is a black block ------------------------ */
[data-slot="segmented"] { display: inline-flex; border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control); }
[data-slot="segmented-item"] {
  white-space: nowrap;
  height: var(--fp-control-sm); padding: 0 var(--fp-space-4);
  border: 0; border-radius: var(--fp-radius-control); background: transparent;
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); color: var(--fp-muted);
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease);
}
[data-slot="segmented-item"]:hover { color: var(--fp-ink); }
[data-slot="segmented-item"]:disabled { opacity: 0.4; pointer-events: none; }
[data-slot="segmented-item"][data-active="true"] { background: var(--fp-accent); color: var(--fp-on-accent); }

/* ---- divider / separator ------------------------------------------------- */
[data-slot="divider"][data-orientation="horizontal"], [data-slot="separator"] {
  border: 0; height: 1px; background: var(--fp-line); margin: 0;
}
[data-slot="divider"][data-orientation="horizontal"][data-with-label="true"] {
  display: flex; align-items: center; gap: var(--fp-space-3);
  height: auto; background: transparent;
  font-size: var(--fp-text-xs); color: var(--fp-muted);
}
[data-slot="divider"][data-with-label="true"]::before,
[data-slot="divider"][data-with-label="true"]::after { content: ""; flex: 1; height: 1px; background: var(--fp-line); }
[data-slot="divider"][data-orientation="vertical"] {
  display: inline-block; width: 1px; height: 1em;
  background: var(--fp-line); vertical-align: middle;
}

/* ---- statistic ----------------------------------------------------------- */
[data-slot="statistic"] { display: flex; flex-direction: column; gap: var(--fp-space-1); }
[data-slot="statistic-label"] { font-size: var(--fp-text-sm); color: var(--fp-muted); }
[data-slot="statistic-value"] { display: flex; align-items: baseline; gap: var(--fp-space-1); }
[data-slot="statistic-number"] {
  font-size: var(--fp-text-2xl); font-weight: var(--fp-weight-semibold);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--fp-tracking-display); line-height: var(--fp-leading-heading);
}
[data-slot="statistic-affix"] { font-size: var(--fp-text-sm); color: var(--fp-muted); }
[data-slot="statistic-footer"] { display: flex; align-items: center; gap: var(--fp-space-2); margin-top: var(--fp-space-1); }
[data-slot="statistic-trend"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-success); }
[data-slot="statistic-trend"][data-direction="down"] { color: var(--fp-danger); }
[data-slot="statistic-hint"] { font-size: var(--fp-text-xs); color: var(--fp-muted); }

/* ---- collapse: lines between items, no outer box ------------------------ */
[data-slot="collapse"] { border-top: 1px solid var(--fp-line); border-bottom: 1px solid var(--fp-line); }
[data-slot="collapse-item"] + [data-slot="collapse-item"] { border-top: 1px solid var(--fp-line); }
[data-slot="collapse-trigger"] {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; height: var(--fp-control-lg); padding: 0;
  border: 0; background: transparent;
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); text-align: left;
}
[data-slot="collapse-icon"] { color: var(--fp-muted); }
[data-slot="collapse-content"] { padding: 0 0 var(--fp-space-4); font-size: var(--fp-text-sm); color: var(--fp-muted); }
[data-slot="collapse-content"][hidden] { display: none; }

/* ---- pagination ---------------------------------------------------------- */
[data-slot="pagination"] { display: inline-flex; align-items: center; gap: var(--fp-space-1); }
[data-slot="pagination-btn"] {
  min-width: var(--fp-control-sm); height: var(--fp-control-sm); padding: 0 var(--fp-space-2);
  display: inline-grid; place-items: center;
  border: 1px solid transparent; border-radius: var(--fp-radius-control);
  background: transparent; font-family: var(--fp-mono); font-size: var(--fp-text-xs);
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="pagination-btn"]:hover:not(:disabled) { border-color: var(--fp-line-strong); }
[data-slot="pagination-btn"][data-active="true"] { background: var(--fp-accent); color: var(--fp-on-accent); border-color: var(--fp-accent); }
[data-slot="pagination-btn"]:disabled { opacity: 0.4; pointer-events: none; }
[data-slot="pagination-ellipsis"] { padding: 0 var(--fp-space-1); color: var(--fp-muted); font-size: var(--fp-text-xs); }

/* ---- kicker: a plain grey line above a heading -------------------------- */
[data-slot="kicker"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); color: var(--fp-muted); }

/* ---- border beam (optional, decorative; not used by any page) ----------- */
@keyframes fp-beam-travel {
  from { stroke-dashoffset: var(--fp-beam-start, 0px); }
  to   { stroke-dashoffset: calc(var(--fp-beam-start, 0px) - var(--fp-beam-len, 0px)); }
}
[data-slot="border-beam"] { isolation: isolate; }

/* ---- masonry ------------------------------------------------------------- */
[data-slot="masonry"] { position: relative; }
[data-slot="masonry-item"] { min-width: 0; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
  [data-slot="border-beam-svg"] { display: none; }
}

/* ==========================================================================
 * Form, overlay and content components (second wave)
 * ========================================================================== */

/* ---- tune scope: a subtree that re-reads type tokens (Create page) ------ */
.fp-tune-scope { font-family: var(--fp-sans); font-size: var(--fp-text-base); line-height: var(--fp-leading-body); color: var(--fp-ink); background: var(--fp-bg); }

/* ---- visually hidden ----------------------------------------------------- */
[data-slot="visually-hidden"] {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ---- textarea ------------------------------------------------------------ */
[data-slot="textarea"] {
  display: block; width: 100%; min-height: 96px;
  padding: var(--fp-space-2) var(--fp-space-3);
  background: transparent;
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-floating);
  font-size: var(--fp-text-sm); line-height: var(--fp-leading-body);
  resize: vertical; outline: none;
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="textarea"]:hover { border-color: var(--fp-muted); }
[data-slot="textarea"]:focus { border-color: var(--fp-accent); }
[data-slot="textarea"]::placeholder { color: var(--fp-muted); }

/* ---- field / fieldset ---------------------------------------------------- */
[data-slot="field"] { display: flex; flex-direction: column; gap: var(--fp-space-2); min-width: 0; }
[data-slot="field-label"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium); }
[data-slot="field-required"] { color: var(--fp-danger); margin-left: var(--fp-space-1); }
[data-slot="field-description"] { font-size: var(--fp-text-xs); color: var(--fp-muted); margin: 0; }
[data-slot="field-error"] { font-size: var(--fp-text-xs); color: var(--fp-danger); margin: 0; }
[data-slot="field"][data-invalid] [data-slot="input"],
[data-slot="field"][data-invalid] [data-slot="textarea"] { border-color: var(--fp-danger); }
[data-slot="fieldset"] { border: 0; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--fp-space-4); min-width: 0; }
[data-slot="fieldset-legend"] { padding: 0; margin-bottom: var(--fp-space-1); font-size: var(--fp-text-base); font-weight: var(--fp-weight-semibold); }

/* ---- number input -------------------------------------------------------- */
[data-slot="number-input"] {
  display: inline-flex; align-items: stretch;
  height: var(--fp-control-md);
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control);
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="number-input"]:hover { border-color: var(--fp-muted); }
[data-slot="number-input"]:focus-within { border-color: var(--fp-accent); }
[data-slot="number-input-field"] {
  width: 72px; min-width: 0; padding: 0 var(--fp-space-2);
  border: 0; background: transparent; outline: none; text-align: center;
  font-family: var(--fp-mono); font-size: var(--fp-text-sm); font-variant-numeric: tabular-nums;
}
[data-slot="number-input-step"] {
  width: var(--fp-control-md); display: grid; place-items: center;
  border: 0; border-radius: var(--fp-radius-surface); background: transparent; color: var(--fp-muted);
  transition: color var(--fp-duration) var(--fp-ease), background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="number-input-step"]:hover { color: var(--fp-ink); background: var(--fp-surface); }
[data-slot="number-input-step"][data-disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="number-input-step"]:first-child { border-right: 1px solid var(--fp-line); }
[data-slot="number-input-step"]:last-child { border-left: 1px solid var(--fp-line); }

/* ---- slider: 1px track, ink fill, square thumb -------------------------- */
[data-slot="slider"] { width: 100%; display: flex; flex-direction: column; gap: var(--fp-space-2); }
[data-slot="slider-header"] { display: flex; justify-content: space-between; align-items: baseline; font-size: var(--fp-text-sm); }
[data-slot="slider-value"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="slider-control"] { position: relative; display: flex; align-items: center; width: 100%; height: 20px; touch-action: none; }
[data-slot="slider-track"] { position: relative; width: 100%; height: 2px; background: var(--fp-line); }
[data-slot="slider-indicator"] { height: 100%; background: var(--fp-accent); }
[data-slot="slider-thumb"] {
  width: 14px; height: 14px; border-radius: var(--fp-radius-control);
  background: var(--fp-bg); border: 1px solid var(--fp-accent);
  transition: background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="slider-thumb"]:hover, [data-slot="slider-thumb"][data-dragging] { background: var(--fp-accent); }
[data-slot="slider-thumb"]:has(:focus-visible) { outline: 2px solid var(--fp-accent); outline-offset: 2px; }
[data-slot="slider"][data-disabled] { opacity: 0.4; pointer-events: none; }

/* ---- combobox / multi-select -------------------------------------------- */
[data-slot="combobox"] { position: relative; display: inline-flex; flex-direction: column; width: 100%; max-width: 320px; }
[data-slot="combobox-control"] {
  display: flex; align-items: center; flex-wrap: wrap; gap: var(--fp-space-1);
  min-height: var(--fp-control-md); padding: 0 var(--fp-space-1) 0 var(--fp-space-3);
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control);
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="combobox-control"]:hover { border-color: var(--fp-muted); }
[data-slot="combobox-control"]:focus-within { border-color: var(--fp-accent); }
/* 8px from the 20px frame to a 12px-radius chip, so the two curves run parallel. */
[data-slot="combobox-control"][data-multiple="true"] { padding: var(--fp-space-1) var(--fp-space-1) var(--fp-space-1) var(--fp-space-2); }
[data-slot="combobox-input"] {
  flex: 1; min-width: 80px; height: calc(var(--fp-control-md) - 2px);
  border: 0; background: transparent; outline: none; font-size: var(--fp-text-sm);
}
[data-slot="combobox-control"][data-multiple="true"] [data-slot="combobox-input"] { height: calc(var(--fp-control-md) - 10px); padding: 0 var(--fp-space-2); }
[data-slot="combobox-input"]::placeholder { color: var(--fp-muted); }
[data-slot="combobox-trigger"], [data-slot="combobox-clear"] {
  width: var(--fp-control-sm); height: var(--fp-control-sm); display: grid; place-items: center; flex-shrink: 0;
  border: 0; background: transparent; color: var(--fp-muted);
}
[data-slot="combobox-trigger"]:hover, [data-slot="combobox-clear"]:hover { color: var(--fp-ink); }
[data-slot="combobox-chip"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-1);
  height: 24px; padding: 0 var(--fp-space-2) 0 var(--fp-space-3);
  border-radius: var(--fp-radius-control); /* removable with ×, so a control: a pill */
  background: var(--fp-accent); color: var(--fp-on-accent);
  font-size: var(--fp-text-xs); font-weight: var(--fp-weight-medium);
}
[data-slot="combobox-chip-remove"] { display: grid; place-items: center; border: 0; padding: 0; background: transparent; color: inherit; opacity: 0.7; }
[data-slot="combobox-chip-remove"]:hover { opacity: 1; }
[data-slot="combobox-content"] {
  min-width: var(--anchor-width); max-height: 280px; overflow-y: auto;
  padding: var(--fp-space-1);
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}
[data-slot="combobox-item"] {
  border-radius: var(--fp-radius-control);
  display: flex; align-items: center; justify-content: space-between; gap: var(--fp-space-3);
  height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  font-size: var(--fp-text-sm); cursor: default; user-select: none;
}
[data-slot="combobox-item"][data-highlighted] { background: var(--fp-surface); }
[data-slot="combobox-item"][data-selected] { font-weight: var(--fp-weight-medium); }
[data-slot="combobox-empty"]:not(:empty) { padding: var(--fp-space-3); font-size: var(--fp-text-sm); color: var(--fp-muted); }

/* ---- toggle group / button group ---------------------------------------- */
[data-slot="toggle-group"], [data-slot="button-group"] { display: inline-flex; }
[data-slot="toggle-group"] > [data-slot="toggle"] + [data-slot="toggle"],
[data-slot="button-group"] > [data-slot="button"] + [data-slot="button"] { margin-left: -1px; }
[data-slot="toggle"] {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--fp-space-2);
  height: var(--fp-control-md); min-width: var(--fp-control-md); padding: 0 var(--fp-space-3);
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control);
  background: transparent; color: var(--fp-muted);
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium);
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="toggle"]:hover { color: var(--fp-ink); }
[data-slot="toggle"][data-pressed] { position: relative; z-index: 1; background: var(--fp-accent); color: var(--fp-on-accent); border-color: var(--fp-accent); }
[data-slot="toggle"][data-disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="toggle-group"][data-size="sm"] [data-slot="toggle"] { height: var(--fp-control-sm); min-width: var(--fp-control-sm); padding: 0 var(--fp-space-2); }
[data-slot="button-group"] > [data-slot="button"]:hover { position: relative; z-index: 1; }
/* Joined groups are one shape: only the outer ends take the control radius. */
[data-slot="toggle-group"] > [data-slot="toggle"]:not(:first-child),
[data-slot="button-group"] > [data-slot="button"]:not(:first-child) { border-top-left-radius: 0; border-bottom-left-radius: 0; }
[data-slot="toggle-group"] > [data-slot="toggle"]:not(:last-child),
[data-slot="button-group"] > [data-slot="button"]:not(:last-child) { border-top-right-radius: 0; border-bottom-right-radius: 0; }
/* A multi-select box grows to several lines, so it cannot be a pill; like the Textarea it takes the rounded field radius. */
[data-slot="combobox-control"][data-multiple="true"] { border-radius: var(--fp-radius-floating); }

/* ---- toolbar: a row of quiet buttons with hairline separators ----------- */
[data-slot="toolbar"] {
  display: flex; align-items: center; gap: var(--fp-space-1);
  padding: var(--fp-space-1); border-bottom: 1px solid var(--fp-line);
}
[data-slot="toolbar-group"] { display: flex; align-items: center; gap: var(--fp-space-1); }
[data-slot="toolbar-button"] {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--fp-space-2);
  height: var(--fp-control-sm); min-width: var(--fp-control-sm); padding: 0 var(--fp-space-2);
  border: 0; border-radius: var(--fp-radius-control); background: transparent; color: var(--fp-ink);
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium);
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease);
}
[data-slot="toolbar-button"]:hover { background: var(--fp-surface); }
[data-slot="toolbar-button"][data-pressed] { background: var(--fp-accent); color: var(--fp-on-accent); }
[data-slot="toolbar-button"][data-disabled] { opacity: 0.4; pointer-events: none; }
[data-slot="toolbar-separator"] { width: 1px; height: 20px; margin: 0 var(--fp-space-1); background: var(--fp-line); }
[data-slot="toolbar-spacer"] { flex: 1; }

/* ---- alert dialog -------------------------------------------------------- */
[data-slot="alert-dialog-content"] {
  position: fixed; z-index: 51; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(420px, calc(100vw - 32px));
  padding: var(--fp-space-6);
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}

/* ---- toast --------------------------------------------------------------- */
[data-slot="toast-viewport"] {
  position: fixed; z-index: 60; right: var(--fp-space-5); bottom: var(--fp-space-5);
  display: flex; flex-direction: column; gap: var(--fp-space-2);
  width: min(360px, calc(100vw - 32px)); outline: none;
}
[data-slot="toast"] {
  display: flex; align-items: flex-start; gap: var(--fp-space-3);
  padding: var(--fp-space-4);
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
  transition: opacity var(--fp-duration) var(--fp-ease);
}
[data-slot="toast"][data-starting-style], [data-slot="toast"][data-ending-style] { opacity: 0; }
[data-slot="toast"][data-limited] { display: none; }
[data-slot="toast-icon"] { flex-shrink: 0; margin-top: 2px; color: var(--fp-ink); }
[data-slot="toast"][data-type="success"] [data-slot="toast-icon"] { color: var(--fp-success); }
[data-slot="toast"][data-type="error"] [data-slot="toast-icon"] { color: var(--fp-danger); }
[data-slot="toast-body"] { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: var(--fp-space-1); }
[data-slot="toast-title"] { margin: 0; font-size: var(--fp-text-sm); font-weight: var(--fp-weight-semibold); }
[data-slot="toast-description"] { margin: 0; font-size: var(--fp-text-sm); color: var(--fp-muted); }
[data-slot="toast-action"] { align-self: flex-start; margin-top: var(--fp-space-2); }
[data-slot="toast-close"] { flex-shrink: 0; border: 0; padding: 0; background: transparent; color: var(--fp-muted); line-height: 0; }
[data-slot="toast-close"]:hover { color: var(--fp-ink); }

/* ---- hover card ---------------------------------------------------------- */
[data-slot="hover-card-trigger"] { color: var(--fp-ink); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; cursor: pointer; }
[data-slot="hover-card-content"] {
  width: 280px; padding: var(--fp-space-4);
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
  font-size: var(--fp-text-sm);
  transition: opacity var(--fp-duration) var(--fp-ease);
}
[data-slot="hover-card-content"][data-starting-style], [data-slot="hover-card-content"][data-ending-style] { opacity: 0; }

/* ---- scroll area: a 1px-wide quiet scrollbar ----------------------------- */
[data-slot="scroll-area"] { position: relative; overflow: hidden; }
[data-slot="scroll-area-viewport"] { width: 100%; height: 100%; overscroll-behavior: contain; outline: none; }
[data-slot="scroll-area-scrollbar"] { display: flex; padding: 2px; opacity: 0; transition: opacity var(--fp-duration) var(--fp-ease); }
[data-slot="scroll-area"]:hover [data-slot="scroll-area-scrollbar"], [data-slot="scroll-area-scrollbar"][data-scrolling] { opacity: 1; }
[data-slot="scroll-area-scrollbar"][data-orientation="vertical"] { width: 8px; }
[data-slot="scroll-area-scrollbar"][data-orientation="horizontal"] { height: 8px; flex-direction: column; }
[data-slot="scroll-area-thumb"] { flex: 1; background: var(--fp-line-strong); border-radius: var(--fp-radius-surface); }

/* ---- command palette ----------------------------------------------------- */
[data-slot="command-content"] {
  position: fixed; z-index: 51; left: 50%; top: 15vh; transform: translateX(-50%);
  width: min(560px, calc(100vw - 32px));
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}
[data-slot="command-input-row"] { display: flex; align-items: center; gap: var(--fp-space-3); padding: 0 var(--fp-space-4); border-bottom: 1px solid var(--fp-line); color: var(--fp-muted); }
[data-slot="command-input"] { flex: 1; height: var(--fp-control-lg); border: 0; background: transparent; outline: none; font-size: var(--fp-text-base); color: var(--fp-ink); }
[data-slot="command-input"]::placeholder { color: var(--fp-muted); }
[data-slot="command-list"] { max-height: 320px; overflow-y: auto; padding: var(--fp-space-2); }
[data-slot="command-group"] { padding: var(--fp-space-2) var(--fp-space-3) var(--fp-space-1); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="command-item"] {
  display: flex; align-items: center; gap: var(--fp-space-3);
  width: 100%; height: var(--fp-control-md); padding: 0 var(--fp-space-3);
  border: 0; border-radius: var(--fp-radius-control); background: transparent; text-align: left;
  font-size: var(--fp-text-sm); color: var(--fp-ink);
}
[data-slot="command-item"][data-active="true"] { background: var(--fp-surface); }
[data-slot="command-item"] [data-slot="kbd"] { margin-left: auto; }
[data-slot="command-empty"] { padding: var(--fp-space-6) var(--fp-space-3); text-align: center; font-size: var(--fp-text-sm); color: var(--fp-muted); }

/* ---- kbd ----------------------------------------------------------------- */
[data-slot="kbd"] {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 20px; padding: 0 var(--fp-space-1);
  border: 1px solid var(--fp-line); border-radius: var(--fp-radius-control);
  font-family: var(--fp-mono); font-size: var(--fp-text-xs); line-height: 1; color: var(--fp-muted);
  white-space: nowrap;
}
[data-slot="kbd-group"] { display: inline-flex; gap: var(--fp-space-1); }

/* ---- spinner: three squares, opacity only, only while loading ------------ */
@keyframes fp-spinner { 0%, 100% { opacity: 0.2; } 33% { opacity: 1; } }
[data-slot="spinner"] { display: inline-flex; align-items: center; gap: 3px; color: var(--fp-ink); }
[data-slot="spinner-dot"] { width: 4px; height: 4px; background: currentColor; opacity: 0.2; animation: fp-spinner 900ms steps(1, end) infinite; }
[data-slot="spinner-dot"]:nth-child(2) { animation-delay: 300ms; }
[data-slot="spinner-dot"]:nth-child(3) { animation-delay: 600ms; }
[data-slot="spinner"][data-size="lg"] { gap: 4px; }
[data-slot="spinner"][data-size="lg"] [data-slot="spinner-dot"] { width: 6px; height: 6px; }
@media (prefers-reduced-motion: reduce) { [data-slot="spinner-dot"] { animation: none; opacity: 0.6; } }

/* ---- avatar group -------------------------------------------------------- */
[data-slot="avatar-group"] { display: inline-flex; align-items: center; }
[data-slot="avatar-group"] > * { outline: 2px solid var(--fp-bg); }
[data-slot="avatar-group"] > * + * { margin-left: -8px; }
[data-slot="avatar-group-more"] { font-family: var(--fp-mono); }

/* ---- code block ---------------------------------------------------------- */
[data-slot="code-block"] { background: var(--fp-surface); min-width: 0; }
[data-slot="code-block-header"] { display: flex; justify-content: space-between; align-items: center; padding: var(--fp-space-2) var(--fp-space-3) 0 var(--fp-space-4); }
[data-slot="code-block-label"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="code-block-pre"] { margin: 0; padding: var(--fp-space-3) var(--fp-space-4) var(--fp-space-4); font-family: var(--fp-mono); font-size: var(--fp-text-sm); line-height: var(--fp-leading-body); color: var(--fp-ink); overflow-x: auto; }
[data-slot="code"] { font-family: var(--fp-mono); font-size: 0.875em; padding: 0 var(--fp-space-1); background: var(--fp-surface); }

/* ---- calendar / date picker --------------------------------------------- */
[data-slot="calendar"] { display: inline-flex; flex-direction: column; gap: var(--fp-space-3); user-select: none; }
[data-slot="calendar-header"] { display: flex; align-items: center; justify-content: space-between; }
[data-slot="calendar-title"] { font-size: var(--fp-text-sm); font-weight: var(--fp-weight-semibold); }
[data-slot="calendar-grid"] { display: grid; grid-template-columns: repeat(7, 36px); }
/* Rows exist for the accessibility tree only; the days stay on the grid. */
[data-slot="calendar-row"] { display: contents; }
[data-slot="calendar-weekday"] { height: 28px; display: grid; place-items: center; font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="calendar-day"] {
  width: 36px; height: 36px; display: grid; place-items: center;
  border: 1px solid transparent; border-radius: var(--fp-radius-surface); background: transparent; padding: 0;
  font-family: var(--fp-mono); font-size: var(--fp-text-sm); font-variant-numeric: tabular-nums; color: var(--fp-ink);
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="calendar-day"]:hover { border-color: var(--fp-line-strong); }
[data-slot="calendar-day"][data-outside="true"] { color: var(--fp-muted); }
[data-slot="calendar-day"][data-today="true"] { border-color: var(--fp-line-strong); }
[data-slot="calendar-day"][data-in-range="true"] { background: var(--fp-surface); }
[data-slot="calendar-day"][data-selected="true"] { background: var(--fp-accent); color: var(--fp-on-accent); border-color: var(--fp-accent); }
[data-slot="calendar-day"]:disabled { opacity: 0.3; pointer-events: none; }
[data-slot="date-picker-trigger"] {
  display: inline-flex; align-items: center; justify-content: space-between; gap: var(--fp-space-3);
  min-width: 220px; height: var(--fp-control-md); padding: 0 var(--fp-space-3);
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control); background: transparent;
  font-size: var(--fp-text-sm); text-align: left;
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="date-picker-trigger"]:hover { border-color: var(--fp-muted); }
[data-slot="date-picker-trigger"][data-popup-open] { border-color: var(--fp-accent); }
[data-slot="date-picker-trigger"] [data-placeholder="true"] { color: var(--fp-muted); }
[data-slot="date-picker-trigger"] svg { color: var(--fp-muted); flex-shrink: 0; }
[data-slot="date-picker-content"] {
  padding: var(--fp-space-4);
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}

/* ---- file input ---------------------------------------------------------- */
[data-slot="file-input"] {
  position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--fp-space-2);
  width: 100%; padding: var(--fp-space-7) var(--fp-space-5);
  border: 1px dashed var(--fp-line-strong); border-radius: var(--fp-radius-surface);
  text-align: center; color: var(--fp-muted); font-size: var(--fp-text-sm);
  cursor: pointer;
  transition: border-color var(--fp-duration) var(--fp-ease), background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="file-input"]:hover { border-color: var(--fp-accent); }
[data-slot="file-input"][data-dragging="true"] { border-color: var(--fp-accent); border-style: solid; background: var(--fp-surface); }
[data-slot="file-input"]:focus-within { outline: 2px solid var(--fp-accent); outline-offset: 2px; }
[data-slot="file-input"] input { position: absolute; width: 1px; height: 1px; opacity: 0; }
[data-slot="file-input-title"] { color: var(--fp-ink); font-weight: var(--fp-weight-medium); }
[data-slot="file-list"] { list-style: none; margin: var(--fp-space-3) 0 0; padding: 0; border-top: 1px solid var(--fp-line); }
[data-slot="file-list-item"] { display: flex; align-items: center; gap: var(--fp-space-3); height: var(--fp-control-lg); border-bottom: 1px solid var(--fp-line); font-size: var(--fp-text-sm); }
[data-slot="file-list-item"] > span:first-of-type { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
[data-slot="file-list-size"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-muted); }

/* ---- tree ---------------------------------------------------------------- */
[data-slot="tree"] { list-style: none; margin: 0; padding: 0; font-size: var(--fp-text-sm); }
[data-slot="tree"] [data-slot="tree"] { padding-left: var(--fp-space-5); }
[data-slot="tree-item"] {
  display: flex; align-items: center; gap: var(--fp-space-2);
  width: 100%; height: var(--fp-control-sm); padding: 0 var(--fp-space-2);
  border: 0; border-radius: var(--fp-radius-surface); background: transparent; color: var(--fp-ink); text-align: left;
  transition: background-color var(--fp-duration) var(--fp-ease);
}
[data-slot="tree-item"]:hover { background: var(--fp-surface); }
[data-slot="tree-item"][data-selected="true"] { background: var(--fp-accent); color: var(--fp-on-accent); }
[data-slot="tree-item"][data-selected="true"] svg { color: var(--fp-on-accent); }
[data-slot="tree-item"] svg { color: var(--fp-muted); flex-shrink: 0; }
[data-slot="tree-chevron"] { width: 16px; display: inline-grid; place-items: center; flex-shrink: 0; }

/* ---- description list ---------------------------------------------------- */
[data-slot="description-list"] { display: grid; grid-template-columns: minmax(96px, max-content) 1fr; margin: 0; font-size: var(--fp-text-sm); }
[data-slot="description-list"] > dt, [data-slot="description-list"] > dd { margin: 0; padding: var(--fp-space-3) 0; border-bottom: 1px solid var(--fp-line); }
[data-slot="description-list"] > dt { padding-right: var(--fp-space-6); color: var(--fp-muted); }
[data-slot="description-list"][data-layout="stacked"] { grid-template-columns: 1fr; }
[data-slot="description-list"][data-layout="stacked"] > dt { padding-bottom: 0; border-bottom: 0; font-size: var(--fp-text-xs); }
[data-slot="description-list"][data-layout="stacked"] > dd { padding-top: var(--fp-space-1); }

/* ---- context menu / menubar --------------------------------------------- */
[data-slot="context-menu-trigger"] {
  display: grid; place-items: center; min-height: 120px; padding: var(--fp-space-5);
  border: 1px dashed var(--fp-line-strong); color: var(--fp-muted); font-size: var(--fp-text-sm);
  user-select: none;
}
[data-slot="menu-content"] {
  min-width: 200px; padding: var(--fp-space-1); outline: none;
  background: var(--fp-bg); border: 1px solid var(--fp-line); border-radius: var(--fp-radius-floating);
  box-shadow: var(--fp-shadow-pop);
}
[data-slot="menu-item"] {
  border-radius: var(--fp-radius-control);
  display: flex; align-items: center; gap: var(--fp-space-3);
  height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  font-size: var(--fp-text-sm); cursor: default; user-select: none; outline: none;
}
[data-slot="menu-item"][data-highlighted] { background: var(--fp-surface); }
[data-slot="menu-item"][data-disabled] { opacity: 0.4; }
[data-slot="menu-item"][data-variant="danger"] { color: var(--fp-danger); }
[data-slot="menu-item"] [data-slot="kbd"] { margin-left: auto; border: 0; padding: 0; }
[data-slot="menu-separator"] { height: 1px; margin: var(--fp-space-1) 0; background: var(--fp-line); }
[data-slot="menubar"] { display: flex; align-items: center; gap: var(--fp-space-1); border-bottom: 1px solid var(--fp-line); padding: var(--fp-space-1); }
[data-slot="menubar-trigger"] {
  height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  border: 0; border-radius: var(--fp-radius-control); background: transparent; color: var(--fp-ink);
  font-size: var(--fp-text-sm); font-weight: var(--fp-weight-medium);
  transition: background-color var(--fp-duration) var(--fp-ease), color var(--fp-duration) var(--fp-ease);
}
[data-slot="menubar-trigger"]:hover { background: var(--fp-surface); }
[data-slot="menubar-trigger"][data-popup-open] { background: var(--fp-accent); color: var(--fp-on-accent); }

/* ---- carousel / lightbox ------------------------------------------------- */
[data-slot="carousel"] { position: relative; display: flex; flex-direction: column; gap: var(--fp-space-3); min-width: 0; }
[data-slot="carousel-viewport"] { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; gap: var(--fp-space-3); }
[data-slot="carousel-viewport"]::-webkit-scrollbar { display: none; }
[data-slot="carousel-slide"] { flex: 0 0 100%; scroll-snap-align: start; min-width: 0; }
[data-slot="carousel-footer"] { display: flex; align-items: center; justify-content: space-between; gap: var(--fp-space-3); }
[data-slot="carousel-count"] { font-family: var(--fp-mono); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="carousel-dots"] { display: flex; gap: var(--fp-space-1); }
[data-slot="carousel-dot"] { width: 16px; height: 2px; padding: 0; border: 0; background: var(--fp-line); transition: background-color var(--fp-duration) var(--fp-ease); }
[data-slot="carousel-dot"][data-active="true"] { background: var(--fp-accent); }
[data-slot="lightbox-content"] {
  position: fixed; inset: 0; z-index: 51;
  display: flex; flex-direction: column;
  background: var(--fp-bg); outline: none;
}
[data-slot="lightbox-bar"] { display: flex; align-items: center; justify-content: space-between; gap: var(--fp-space-3); height: 56px; padding: 0 var(--fp-space-4); border-bottom: 1px solid var(--fp-line); }
[data-slot="lightbox-stage"] { flex: 1; min-height: 0; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: var(--fp-space-4); padding: var(--fp-space-5); }
[data-slot="lightbox-image"] { width: 100%; height: 100%; min-height: 0; object-fit: contain; display: block; background: var(--fp-surface); }
[data-slot="lightbox-thumbs"] { display: flex; gap: var(--fp-space-2); padding: var(--fp-space-3) var(--fp-space-4); border-top: 1px solid var(--fp-line); overflow-x: auto; }
[data-slot="lightbox-thumb"] { flex: 0 0 64px; height: 48px; padding: 0; border: 1px solid transparent; background: var(--fp-surface); opacity: 0.6; transition: opacity var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease); }
[data-slot="lightbox-thumb"] img { width: 100%; height: 100%; object-fit: cover; display: block; }
[data-slot="lightbox-thumb"][data-active="true"] { opacity: 1; border-color: var(--fp-accent); }
[data-slot="lightbox-open"] { display: block; padding: 0; border: 0; background: transparent; cursor: zoom-in; width: 100%; }

/* ---- timestamp / status dot --------------------------------------------- */
[data-slot="timestamp"] { font-variant-numeric: tabular-nums; color: var(--fp-muted); font-size: var(--fp-text-sm); }
[data-slot="status-dot"] { display: inline-flex; align-items: center; gap: var(--fp-space-2); font-size: var(--fp-text-sm); }
[data-slot="status-dot-mark"] { width: 8px; height: 8px; flex-shrink: 0; border-radius: var(--fp-radius-control); background: var(--fp-accent); }
[data-slot="status-dot"][data-status="success"] [data-slot="status-dot-mark"] { background: var(--fp-success); }
[data-slot="status-dot"][data-status="danger"] [data-slot="status-dot-mark"] { background: var(--fp-danger); }
[data-slot="status-dot"][data-status="idle"] [data-slot="status-dot-mark"] { background: transparent; border: 1px solid var(--fp-line-strong); }
[data-slot="status-dot"][data-status="success"] { color: var(--fp-success); }
[data-slot="status-dot"][data-status="danger"] { color: var(--fp-danger); }
[data-slot="status-dot"][data-status="idle"] { color: var(--fp-muted); }

/* ---- AI parts: message, thinking, tool call, task list, approval --------- */
[data-slot="message"] { display: flex; gap: var(--fp-space-3); align-items: flex-start; }
[data-slot="message"][data-role="user"] { flex-direction: row-reverse; }
[data-slot="message-body"] { max-width: 80%; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: var(--fp-space-3); font-size: var(--fp-text-sm); line-height: var(--fp-leading-body); }
[data-slot="message"][data-role="user"] [data-slot="message-body"] { background: var(--fp-surface); padding: var(--fp-space-2) var(--fp-space-3); border-radius: var(--fp-radius-surface); }

[data-slot="thinking"] { font-size: var(--fp-text-sm); }
[data-slot="thinking-trigger"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-2);
  padding: 0; border: 0; background: transparent; color: var(--fp-muted); font: inherit;
  transition: color var(--fp-duration) var(--fp-ease);
}
[data-slot="thinking-trigger"]:hover { color: var(--fp-ink); }
[data-slot="thinking-icon"] { transition: transform var(--fp-duration) var(--fp-ease); }
[data-slot="thinking-trigger"][data-panel-open] [data-slot="thinking-icon"] { transform: rotate(180deg); }
[data-slot="thinking-content"] { margin-top: var(--fp-space-2); padding-left: var(--fp-space-3); border-left: 1px solid var(--fp-line); color: var(--fp-muted); display: flex; flex-direction: column; gap: var(--fp-space-2); }
[data-slot="thinking-content"][hidden] { display: none; }

[data-slot="tool-call"] {
  display: inline-flex; align-items: center; gap: var(--fp-space-2); max-width: 100%;
  height: var(--fp-control-sm); padding: 0 var(--fp-space-3);
  border: 1px solid var(--fp-line); border-radius: var(--fp-radius-control);
  font-size: var(--fp-text-xs); color: var(--fp-ink);
}
[data-slot="tool-call"] svg { flex-shrink: 0; }
[data-slot="tool-call-name"] { white-space: nowrap; }
[data-slot="tool-call-detail"] { color: var(--fp-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
[data-slot="tool-call"][data-status="done"] svg { color: var(--fp-success); }
[data-slot="tool-call"][data-status="error"] svg { color: var(--fp-danger); }

[data-slot="task-list"] { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--fp-line); }
[data-slot="task"] { display: flex; align-items: center; gap: var(--fp-space-3); padding: var(--fp-space-3) 0; border-bottom: 1px solid var(--fp-line); font-size: var(--fp-text-sm); }
[data-slot="task-marker"] { display: inline-flex; align-items: center; justify-content: center; width: var(--fp-icon); flex-shrink: 0; color: var(--fp-muted); }
[data-slot="task"][data-status="done"] [data-slot="task-marker"] { color: var(--fp-success); }
[data-slot="task"][data-status="failed"] [data-slot="task-marker"] { color: var(--fp-danger); }
[data-slot="task-title"] { flex: 1; min-width: 0; }
[data-slot="task"][data-status="queued"] [data-slot="task-title"] { color: var(--fp-muted); }
[data-slot="task-detail"] { color: var(--fp-muted); font-size: var(--fp-text-xs); white-space: nowrap; }
[data-slot="task"][data-status="failed"] [data-slot="task-detail"] { color: var(--fp-danger); }

/* In the message flow, so a content surface: one border, no shadow. */
[data-slot="approval"] {
  display: flex; flex-direction: column; gap: var(--fp-space-3); width: 100%; max-width: 480px;
  font-size: var(--fp-text-sm);
  padding: var(--fp-space-4); background: var(--fp-bg);
  border: 1px solid var(--fp-line); border-radius: var(--fp-radius-surface);
}
[data-slot="approval-title"] { font-weight: var(--fp-weight-semibold); }
[data-slot="approval-description"] { color: var(--fp-muted); }
[data-slot="approval-footer"] { display: flex; justify-content: flex-end; gap: var(--fp-space-2); }
[data-slot="approval-result"] { display: inline-flex; align-items: center; gap: var(--fp-space-2); color: var(--fp-muted); }
[data-slot="approval"][data-status="approved"] [data-slot="approval-result"] svg { color: var(--fp-success); }
[data-slot="approval"][data-status="denied"] [data-slot="approval-result"] svg { color: var(--fp-danger); }
[data-slot="diff"] { margin: 0; background: var(--fp-surface); border-radius: var(--fp-radius-surface); padding: var(--fp-space-2) 0; max-width: 100%; overflow-x: auto; }
[data-slot="diff-file"] { display: flex; align-items: center; gap: var(--fp-space-2); padding: 0 var(--fp-space-3) var(--fp-space-2); font-size: var(--fp-text-xs); color: var(--fp-muted); }
[data-slot="diff-body"] { margin: 0; font-family: var(--fp-mono); font-size: var(--fp-text-xs); line-height: 1.8; }
[data-slot="diff-line"] { display: block; padding: 0 var(--fp-space-3); white-space: pre; }
[data-slot="diff-marker"] { display: inline-block; width: 2ch; }
[data-slot="diff-line"][data-kind="add"] { color: var(--fp-success); }
[data-slot="diff-line"][data-kind="del"] { color: var(--fp-danger); text-decoration: line-through; text-decoration-thickness: 1px; }
[data-slot="diff-line"][data-kind="hunk"] { color: var(--fp-muted); }
/* Plain inline, so punctuation after it stays on the same line. */
[data-slot="diff-value"] { white-space: nowrap; }
[data-slot="diff-value-from"] { margin-right: var(--fp-space-2); color: var(--fp-danger); text-decoration: line-through; text-decoration-thickness: 1px; }
[data-slot="diff-value-to"] { color: var(--fp-success); text-decoration: none; }

[data-slot="citation"] {
  display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 var(--fp-space-1);
  margin-inline: 2px; vertical-align: baseline;
  border: 1px solid var(--fp-line); border-radius: var(--fp-radius-control);
  font-family: var(--fp-mono); font-size: var(--fp-text-xs); line-height: 1; color: var(--fp-muted); text-decoration: none;
  transition: color var(--fp-duration) var(--fp-ease), border-color var(--fp-duration) var(--fp-ease);
}
a[data-slot="citation"]:hover { color: var(--fp-ink); border-color: var(--fp-line-strong); }
[data-slot="sources"] { display: flex; flex-direction: column; gap: var(--fp-space-2); font-size: var(--fp-text-sm); }
[data-slot="sources-label"] { color: var(--fp-muted); font-size: var(--fp-text-xs); }
[data-slot="sources-list"] { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--fp-space-2); }
[data-slot="source"] { display: flex; gap: var(--fp-space-3); align-items: baseline; }
[data-slot="source-number"] { width: var(--fp-space-4); flex-shrink: 0; color: var(--fp-muted); font-size: var(--fp-text-xs); }
[data-slot="source-text"] { display: flex; flex-wrap: wrap; gap: 0 var(--fp-space-2); align-items: baseline; min-width: 0; }
[data-slot="source-note"] { color: var(--fp-muted); font-size: var(--fp-text-xs); }

/* Icons inside 16px controls keep a heavier stroke so they stay legible. */
[data-slot="checkbox-box"] svg.lucide { stroke-width: 2.5; }



/* ==========================================================================
 * Control sizes. Every form control takes size="sm" | "md" | "lg" and maps
 * to the same three heights as Button (32 / 40 / 48). Controls that sit in
 * one row must share one size. Default is md everywhere.
 * ========================================================================== */
[data-slot="input"][data-size="sm"],
[data-slot="select-trigger"][data-size="sm"],
[data-slot="number-input"][data-size="sm"],
[data-slot="date-picker-trigger"][data-size="sm"] { height: var(--fp-control-sm); }
[data-slot="combobox-control"][data-size="sm"] { min-height: var(--fp-control-sm); }
[data-slot="input"][data-size="lg"],
[data-slot="select-trigger"][data-size="lg"],
[data-slot="number-input"][data-size="lg"],
[data-slot="date-picker-trigger"][data-size="lg"] { height: var(--fp-control-lg); }
[data-slot="combobox-control"][data-size="lg"] { min-height: var(--fp-control-lg); }

/* Segmented: the outer 1px border is part of the height, so items are 2px shorter. */
[data-slot="segmented"] { --fp-h: var(--fp-control-md); height: var(--fp-h); max-width: 100%; overflow-x: auto; scrollbar-width: none; }
[data-slot="segmented"]::-webkit-scrollbar { display: none; }
[data-slot="segmented"][data-size="sm"] { --fp-h: var(--fp-control-sm); }
[data-slot="segmented"][data-size="lg"] { --fp-h: var(--fp-control-lg); }
[data-slot="segmented-item"] { height: calc(var(--fp-h) - 2px); flex-shrink: 0; }
[data-slot="segmented"][data-size="sm"] [data-slot="segmented-item"] { padding: 0 var(--fp-space-3); }

/* ==========================================================================
 * Text that must stay on one line: truncate instead of wrapping or clipping.
 * ========================================================================== */
[data-slot="sidebar-item"] { min-width: 0; }
[data-slot="sidebar-item"] > [data-slot="sidebar-item-text"] { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
[data-slot="sidebar-item"] > svg { flex-shrink: 0; }
[data-slot="progress-header"] { gap: var(--fp-space-3); min-width: 0; }
[data-slot="progress-label"] { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
[data-slot="progress-value"] { flex-shrink: 0; }
[data-slot="badge"] { flex-shrink: 0; }
[data-slot="card-title"] { overflow-wrap: anywhere; }
[data-slot="table-head"] { white-space: nowrap; }

/* Statistic: the number scales with the card instead of overflowing it. */
/* A card holding a Statistic is a size container, so the number scales to the
   card. Opt-in only: a size container collapses when its width comes from content. */
[data-slot="card"]:has([data-slot="statistic"]) { container-type: inline-size; }
[data-slot="statistic"] { min-width: 0; }
[data-slot="statistic-value"] {
  font-size: clamp(var(--fp-text-xl), 22cqi, var(--fp-text-2xl));
  white-space: nowrap; min-width: 0;
}
[data-slot="statistic-number"] { font-size: 1em; }
[data-slot="statistic-affix"] { font-size: 0.5em; line-height: 1; }
[data-slot="statistic-footer"] { flex-wrap: wrap; row-gap: 0; }
[data-slot="statistic-trend"], [data-slot="statistic-hint"] { white-space: nowrap; }

/* ---- input: filled variant and icon group --------------------------------- */
/* Filled: a translucent ink tint, so it stays visible on white and on grey surfaces. */
[data-slot="input"][data-variant="filled"] { background: color-mix(in srgb, var(--fp-ink) 6%, transparent); border-color: transparent; }
[data-slot="input"][data-variant="filled"]:hover { border-color: var(--fp-line); }
[data-slot="input"][data-variant="filled"]:focus { border-color: var(--fp-accent); }
[data-slot="input-group"] {
  display: flex; align-items: center; gap: var(--fp-space-2);
  width: 100%; height: var(--fp-control-md); padding: 0 var(--fp-space-3);
  border: 1px solid var(--fp-line-strong); border-radius: var(--fp-radius-control);
  background: transparent; color: var(--fp-ink);
  transition: border-color var(--fp-duration) var(--fp-ease);
}
[data-slot="input-group"][data-size="sm"] { height: var(--fp-control-sm); }
[data-slot="input-group"][data-size="lg"] { height: var(--fp-control-lg); }
[data-slot="input-group"]:hover { border-color: var(--fp-muted); }
[data-slot="input-group"]:focus-within { border-color: var(--fp-accent); }
[data-slot="input-group"][data-variant="filled"] { background: color-mix(in srgb, var(--fp-ink) 6%, transparent); border-color: transparent; }
[data-slot="input-group"][data-variant="filled"]:hover { border-color: var(--fp-line); }
[data-slot="input-group"][data-variant="filled"]:focus-within { border-color: var(--fp-accent); }
[data-slot="input-group"][data-disabled="true"] { opacity: 0.4; pointer-events: none; }
[data-slot="input-group"]:has(:focus-visible) { outline: 2px solid var(--fp-accent); outline-offset: 2px; }
[data-slot="input-bare"] {
  flex: 1; min-width: 0; height: 100%; padding: 0;
  border: 0; outline: none; background: transparent;
