import * as React from 'react'
import { AlertDialog as BaseAlertDialog } from '@base-ui/react/alert-dialog'

export type AlertDialogProps = {
  /** The element that opens the dialog, usually a Button. */
  trigger: React.ReactElement<Record<string, unknown>>
  title: React.ReactNode
  description?: React.ReactNode
  confirmLabel?: React.ReactNode
  cancelLabel?: React.ReactNode
  /** Destructive action: the confirm button becomes an outline with red text. */
  danger?: boolean
  /** Controlled (`open` + `onOpenChange`) or uncontrolled (`defaultOpen`). */
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  onConfirm?: () => void
  /** Keep the confirm button inert, e.g. while a request is running. */
  confirmDisabled?: boolean
}

/** "Delete this project?" — a modal that needs an explicit answer. */
export function AlertDialog({ trigger, title, description, confirmLabel = 'Confirm', cancelLabel = 'Cancel', danger, open, defaultOpen, onOpenChange, onConfirm, confirmDisabled }: AlertDialogProps) {
  return (
    <BaseAlertDialog.Root open={open} defaultOpen={defaultOpen} onOpenChange={(o) => onOpenChange?.(o)}>
      <BaseAlertDialog.Trigger render={trigger} />
      <BaseAlertDialog.Portal>
        <BaseAlertDialog.Backdrop data-slot="dialog-overlay" />
        <BaseAlertDialog.Popup data-slot="alert-dialog-content">
          <div data-slot="dialog-header">
            <BaseAlertDialog.Title data-slot="dialog-title">{title}</BaseAlertDialog.Title>
            {description != null && <BaseAlertDialog.Description data-slot="dialog-description">{description}</BaseAlertDialog.Description>}
          </div>
          <div data-slot="dialog-footer">
            <BaseAlertDialog.Close data-slot="button" data-variant="outline">{cancelLabel}</BaseAlertDialog.Close>
            <BaseAlertDialog.Close
              data-slot="button"
              data-variant={danger ? 'outline' : 'default'}
              style={danger ? { color: 'var(--fp-danger)' } : undefined}
              disabled={confirmDisabled}
              onClick={onConfirm}
            >
              {confirmLabel}
            </BaseAlertDialog.Close>
          </div>
        </BaseAlertDialog.Popup>
      </BaseAlertDialog.Portal>
    </BaseAlertDialog.Root>
  )
}

import * as React from 'react'
import { CheckCircle2, Info, AlertCircle, XCircle, X } from 'lucide-react'

type Variant = 'info' | 'success' | 'warning' | 'error'
export type AlertProps = Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> & {
  variant?: Variant
  title?: React.ReactNode
  onClose?: () => void
  /** Accessible name of the close button, for localized products. */
  closeLabel?: string
}

const ICONS: Record<Variant, React.ReactNode> = {
  info: <Info size={16} />,
  success: <CheckCircle2 size={16} />,
  warning: <AlertCircle size={16} />,
  error: <XCircle size={16} />,
}

export function Alert({ variant = 'info', title, children, onClose, closeLabel = 'Close', ...props }: AlertProps) {
  return (
    <div data-slot="alert" data-variant={variant} role="alert" {...props}>
      <span data-slot="alert-icon">{ICONS[variant]}</span>
      <div data-slot="alert-body">
        {title && <div data-slot="alert-title">{title}</div>}
        {children && <div data-slot="alert-description">{children}</div>}
      </div>
      {onClose && (
        <button data-slot="alert-close" type="button" onClick={onClose} aria-label={closeLabel}>
          <X size={16} />
        </button>
      )}
    </div>
  )
}

import * as React from 'react'
import { Check, X } from 'lucide-react'
import { Button } from '@/components/ui/button'

export type ApprovalStatus = 'pending' | 'approved' | 'denied'

export type ApprovalProps = Omit<React.ComponentProps<'div'>, 'title' | 'onChange'> & {
  /** What the assistant wants to do: "Delete 12 draft orders?" */
  title: React.ReactNode
  description?: React.ReactNode
  /** Details to check before deciding: a CodeBlock, a list of the items affected. */
  children?: React.ReactNode
  /** Controlled status. Without it the component keeps its own, starting at `defaultStatus`. */
  status?: ApprovalStatus
  defaultStatus?: ApprovalStatus
  onApprove?: () => void
  onDeny?: () => void
  approveLabel?: string
  denyLabel?: string
  approvedLabel?: string
  deniedLabel?: string
}

/**
 * A question the assistant asks before it acts, placed in the message flow. It shows two buttons
 * until the user decides, then the buttons give way to the result so the history reads correctly.
 */
export function Approval({
  title, description, children, status, defaultStatus = 'pending', onApprove, onDeny,
  approveLabel = 'Approve', denyLabel = 'Deny', approvedLabel = 'Approved', deniedLabel = 'Denied', ...props
}: ApprovalProps) {
  const [inner, setInner] = React.useState<ApprovalStatus>(defaultStatus)
  const current = status ?? inner
  const id = React.useId()
  const decide = (next: ApprovalStatus, cb?: () => void) => {
    if (status === undefined) setInner(next)
    cb?.()
  }
  return (
    <div data-slot="approval" data-status={current} role="group" aria-labelledby={`${id}-title`} {...props}>
      <div data-slot="approval-title" id={`${id}-title`}>{title}</div>
      {description && <div data-slot="approval-description">{description}</div>}
      {children}
      <div data-slot="approval-footer" aria-live="polite">
        {current === 'pending' ? (
          <>
            <Button size="sm" variant="outline" onClick={() => decide('denied', onDeny)}>{denyLabel}</Button>
            <Button size="sm" onClick={() => decide('approved', onApprove)}>{approveLabel}</Button>
          </>
        ) : (
          <span data-slot="approval-result">
            {current === 'approved' ? <Check size={16} aria-hidden="true" /> : <X size={16} aria-hidden="true" />}
            {current === 'approved' ? approvedLabel : deniedLabel}
          </span>
        )}
      </div>
    </div>
  )
}

