import * as React from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { Search } from 'lucide-react'
import { Kbd } from '@/components/ui/kbd'

export type Command = {
  id: string
  label: string
  group?: string
  icon?: React.ReactNode
  shortcut?: string
  keywords?: string[]
  onSelect: () => void
}

export type CommandPaletteProps = {
  commands: Command[]
  open?: boolean
  onOpenChange?: (open: boolean) => void
  /** Bind ⌘K / Ctrl+K to open. On by default. */
  hotkey?: boolean
  placeholder?: string
  emptyText?: string
  /** Accessible name of the dialog, for localized products. */
  label?: string
  className?: string
  /** Replace the default matching (label, group and keywords contain the query). */
  filter?: (command: Command, query: string) => boolean
  /** The key that opens it together with ⌘ / Ctrl. Default "k". */
  hotkeyKey?: string
  /** Text of the key hint at the right of the field. */
  closeHint?: string
}

/** ⌘K search over a list of commands. Arrow keys move, Enter runs, Esc closes. */
export function CommandPalette({ commands, open: openProp, onOpenChange, hotkey = true, placeholder = 'Type a command or search…', emptyText = 'No results', label = 'Command palette', className, filter, hotkeyKey = 'k', closeHint = 'Esc' }: CommandPaletteProps) {
  const [openState, setOpenState] = React.useState(false)
  const open = openProp ?? openState
  const setOpen = React.useCallback((o: boolean) => { setOpenState(o); onOpenChange?.(o) }, [onOpenChange])
  const [query, setQuery] = React.useState('')
  const [active, setActive] = React.useState(0)
  const listId = React.useId()

  React.useEffect(() => {
    if (!hotkey) return
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === hotkeyKey.toLowerCase()) { e.preventDefault(); setOpen(!open) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [hotkey, hotkeyKey, open, setOpen])

  React.useEffect(() => { if (!open) { setQuery(''); setActive(0) } }, [open])

  const q = query.trim().toLowerCase()
  const results = q
    ? commands.filter((c) => (filter ? filter(c, q) : [c.label, c.group ?? '', ...(c.keywords ?? [])].some((s) => s.toLowerCase().includes(q))))
    : commands
  const run = (c?: Command) => { if (!c) return; setOpen(false); c.onSelect() }

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => Math.min(i + 1, results.length - 1)) }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)) }
    else if (e.key === 'Enter') { e.preventDefault(); run(results[active]) }
  }

  let lastGroup: string | undefined
  return (
    <BaseDialog.Root open={open} onOpenChange={(o) => setOpen(o)}>
      <BaseDialog.Portal>
        <BaseDialog.Backdrop data-slot="dialog-overlay" />
        <BaseDialog.Popup data-slot="command-content" className={className} aria-label={label}>
          <div data-slot="command-input-row">
            <Search size={16} />
            <input
              data-slot="command-input"
              autoFocus
              value={query}
              placeholder={placeholder}
              aria-label={label}
              onChange={(e) => { setQuery(e.target.value); setActive(0) }}
              onKeyDown={onKeyDown}
              role="combobox"
              aria-expanded="true"
              aria-controls={listId}
              aria-activedescendant={results[active] ? `${listId}-${results[active].id}` : undefined}
            />
            <Kbd>{closeHint}</Kbd>
          </div>
          <div data-slot="command-list" id={listId} role="listbox">
            {results.length === 0 && <div data-slot="command-empty">{emptyText}</div>}
            {results.map((c, i) => {
              const header = c.group && c.group !== lastGroup ? c.group : null
              lastGroup = c.group
              return (
                <React.Fragment key={c.id}>
                  {header && <div data-slot="command-group">{header}</div>}
                  <button
                    type="button"
                    id={`${listId}-${c.id}`}
                    data-slot="command-item"
                    data-active={i === active}
                    role="option"
                    aria-selected={i === active}
                    tabIndex={-1}
                    onMouseMove={() => setActive(i)}
                    onClick={() => run(c)}
                  >
                    {c.icon}
                    <span>{c.label}</span>
                    {c.shortcut && <Kbd>{c.shortcut}</Kbd>}
                  </button>
                </React.Fragment>
              )
            })}
          </div>
        </BaseDialog.Popup>
      </BaseDialog.Portal>
    </BaseDialog.Root>
  )
}

import * as React from 'react'
import { ArrowUp, Square } from 'lucide-react'
import { Button } from '@/components/ui/button'

export type ComposerProps = Omit<React.ComponentProps<'div'>, 'onSubmit' | 'defaultValue' | 'onChange'> & {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Called with the trimmed text when the user presses Enter or the send button. Empty text is ignored. */
  onSubmit?: (value: string) => void
  /** Called when the stop button is pressed while `loading`. */
  onStop?: () => void
  /** A reply is being produced: the send button becomes a stop button. */
  loading?: boolean
  disabled?: boolean
  placeholder?: string
  /** The textarea grows with its text up to this many lines, then scrolls. Default 8. */
  maxRows?: number
  /** Left of the bar: attach buttons, a model picker or a key hint. */
  leading?: React.ReactNode
  /** Right of the bar, before the send button. */
  actions?: React.ReactNode
  /** Clear the text after a successful submit. Default true; set false when the parent clears it. */
  clearOnSubmit?: boolean
  /** Accessible names, for localized products. */
  inputLabel?: string
  sendLabel?: string
  stopLabel?: string
}

/**
 * The message box of a chat or assistant screen: a growing textarea, a bar for actions and a send
 * button. Enter sends and Shift+Enter adds a line. Enter during IME composition (pinyin, kana)
 * only confirms the text, it never sends. Controlled (`value` + `onValueChange`) or uncontrolled.
 */
export function Composer({
  value, defaultValue = '', onValueChange, onSubmit, onStop, loading = false, disabled = false,
  placeholder, maxRows = 8, leading, actions, clearOnSubmit = true,
  inputLabel = 'Message', sendLabel = 'Send', stopLabel = 'Stop', className, ...rest
}: ComposerProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const controlled = value !== undefined
  const text = controlled ? value : inner
  const ref = React.useRef<HTMLTextAreaElement>(null)

  const fit = React.useCallback(() => {
    const el = ref.current
    if (!el) return
    el.style.height = 'auto'
    const line = parseFloat(getComputedStyle(el).lineHeight) || 22
    const pad = parseFloat(getComputedStyle(el).paddingTop) + parseFloat(getComputedStyle(el).paddingBottom)
    el.style.height = `${Math.min(el.scrollHeight, line * maxRows + pad)}px`
  }, [maxRows])
  React.useLayoutEffect(fit, [text, fit])

  const set = (v: string) => {
    if (!controlled) setInner(v)
    onValueChange?.(v)
  }
  const canSend = !disabled && !loading && text.trim().length > 0
  const send = () => {
    if (!canSend) return
    onSubmit?.(text.trim())
    if (clearOnSubmit) set('')
  }

  return (
    <div data-slot="composer" data-disabled={disabled ? 'true' : undefined} className={className} {...rest}>
      <textarea
        ref={ref}
        data-slot="composer-input"
        rows={1}
        value={text}
        disabled={disabled}
        placeholder={placeholder}
        aria-label={inputLabel}
        onChange={(e) => set(e.target.value)}
        onKeyDown={(e) => {
          if (e.key !== 'Enter' || e.shiftKey || e.nativeEvent.isComposing || e.keyCode === 229) return
          e.preventDefault()
          send()
        }}
      />
      <div data-slot="composer-bar">
        <div data-slot="composer-leading">{leading}</div>
        <div data-slot="composer-actions">
          {actions}
          {loading ? (
            <Button size="icon" aria-label={stopLabel} onClick={onStop}><Square size={16} /></Button>
          ) : (
            <Button size="icon" aria-label={sendLabel} disabled={!canSend} onClick={send}><ArrowUp size={16} /></Button>
          )}
        </div>
      </div>
    </div>
  )
}

