import * as React from 'react'

type ImageProps = React.ImgHTMLAttributes<HTMLImageElement> & {
  ratio?: 'square' | '4:3' | '16:9' | '3:4'
  fallback?: React.ReactNode
}

export function Image({ ratio = '4:3', alt = '', className, fallback, ...props }: ImageProps) {
  const [failed, setFailed] = React.useState(false)
  return (
    <div data-slot="image" data-ratio={ratio} className={className}>
      {failed || !props.src
        ? (fallback ?? <span data-slot="image-fallback" role="img" aria-label={alt || undefined} />)
        : <img data-slot="image-element" alt={alt} onError={() => setFailed(true)} {...props} />}
    </div>
  )
}

import * as React from 'react'
import { Input as BaseInput } from '@base-ui/react/input'
import { Button, type ButtonProps } from '@/components/ui/button'
import type { ControlSize } from '@/components/ui/input'

export type InputGroupProps = Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> & {
  size?: ControlSize
  variant?: 'outline' | 'filled'
  disabled?: boolean
  children: React.ReactNode
}

/**
 * One field frame around an input plus addons and buttons, drawn once so focus and error states
 * cover the whole row. Put `InputGroupInput` in it, with any number of `InputGroupAddon` (icon,
 * unit, Kbd) and `InputGroupButton` before or after. For a single icon on either side, `Input`'s
 * `leading` / `trailing` props are shorter.
 */
export function InputGroup({ size: sizeProp = 'md', variant = 'outline', disabled, className, ...props }: InputGroupProps) {
  const size = sizeProp === 'default' ? 'md' : sizeProp
  return <div data-slot="input-group" role="group" data-size={size} data-variant={variant} data-disabled={disabled ? 'true' : undefined} className={className} {...props} />
}

/** Icon or short text inside the frame. Pass `aria-hidden` on a purely decorative icon. */
export function InputGroupAddon({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span data-slot="input-adornment" className={className} {...props} />
}

/** The text input. A Base UI input, so it joins Field and forwards `ref`. */
export function InputGroupInput({ className, ...props }: React.ComponentProps<'input'>) {
  return <BaseInput data-slot="input-bare" className={className} {...props} />
}

/** A small button sitting inside the frame, e.g. Copy or Search. */
export function InputGroupButton({ size = 'sm', variant = 'secondary', ...props }: ButtonProps) {
  return <Button size={size} variant={variant} {...props} />
}

import * as React from 'react'
import { Input as BaseInput } from '@base-ui/react/input'

/** `default` is accepted as an alias of `md`, the name Button uses. */
export type ControlSize = 'sm' | 'md' | 'default' | 'lg'

export type InputProps = Omit<React.ComponentProps<'input'>, 'size'> & {
  /** sm 32 / md 40 / lg 48, same as Button. Controls in one row share one size. */
  size?: ControlSize
  /** The native `size` attribute: the visible width in characters. */
  htmlSize?: number
  /** outline: 1px border (default). filled: light grey fill, no border, e.g. a search box. */
  variant?: 'outline' | 'filled'
  /** Icon before the text, e.g. <Search />. */
  leading?: React.ReactNode
  /** Icon or short text after the text, e.g. a unit or <Kbd>. */
  trailing?: React.ReactNode
}

/**
 * A Base UI input, so it joins Field (labels, validity, dirty/touched) and forwards `ref`.
 * Every native input attribute passes through.
 */
export function Input({ className, style, size: sizeProp = 'md', htmlSize, variant = 'outline', leading, trailing, ...props }: InputProps) {
  const size = sizeProp === 'default' ? 'md' : sizeProp
  if (leading == null && trailing == null) {
    return <BaseInput data-slot="input" data-size={size} data-variant={variant} size={htmlSize} className={className} style={style} {...props} />
  }
  // With icons the group draws the field; the inner input is bare.
  return (
    <div data-slot="input-group" data-size={size} data-variant={variant} data-disabled={props.disabled ? 'true' : undefined} className={className} style={style}>
      {leading != null && <span data-slot="input-adornment" aria-hidden="true">{leading}</span>}
      <BaseInput data-slot="input-bare" size={htmlSize} {...props} />
      {trailing != null && <span data-slot="input-adornment">{trailing}</span>}
    </div>
  )
}

export function Label({ className, ...props }: React.LabelHTMLAttributes<HTMLLabelElement>) {
  return <label data-slot="label" className={className} {...props} />
}

import * as React from 'react'

export function Kbd({ children, ...props }: React.HTMLAttributes<HTMLElement>) {
  return <kbd data-slot="kbd" {...props}>{children}</kbd>
}

/** A shortcut such as ⌘ K: one key per box. */
export function KbdGroup({ keys }: { keys: string[] }) {
  return (
    <span data-slot="kbd-group">
      {keys.map((k) => <Kbd key={k}>{k}</Kbd>)}
    </span>
  )
}

import * as React from 'react'
import { Dialog as BaseDialog } from '@base-ui/react/dialog'
import { ChevronLeft, ChevronRight, X } from 'lucide-react'

export type LightboxImage = { src: string; alt: string; thumb?: string }

export type LightboxProps = {
  images: LightboxImage[]
  open: boolean
  index: number
  onOpenChange: (open: boolean) => void
  onIndexChange: (index: number) => void
  className?: string
  /** What this dialog is called by assistive technology (its role description). The dialog's name is the current image's alt. */
  label?: string
  closeLabel?: string
  previousLabel?: string
  nextLabel?: string
}

/** Full-screen image viewer. ← / → change image, Esc closes. */
export function Lightbox({ images, open, index, onOpenChange, onIndexChange, className, label = 'Image viewer', closeLabel = 'Close', previousLabel = 'Previous image', nextLabel = 'Next image' }: LightboxProps) {
  const img = images[index]
  const go = (i: number) => onIndexChange((i + images.length) % images.length)
  return (
    <BaseDialog.Root open={open} onOpenChange={(o) => onOpenChange(o)}>
      <BaseDialog.Portal>
        <BaseDialog.Popup
          data-slot="lightbox-content"
          className={className}
          aria-roledescription={label}
          onKeyDown={(e) => { if (e.key === 'ArrowRight') go(index + 1); if (e.key === 'ArrowLeft') go(index - 1) }}
        >
          <div data-slot="lightbox-bar">
            <BaseDialog.Title style={{ margin: 0, fontSize: 'var(--fp-text-sm)', fontWeight: 'var(--fp-weight-medium)' }}>{img?.alt}</BaseDialog.Title>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--fp-space-3)' }}>
              <span className="fp-num fp-muted" style={{ fontSize: 'var(--fp-text-xs)' }}>{index + 1} / {images.length}</span>
              <BaseDialog.Close data-slot="button" data-variant="ghost" data-size="icon" aria-label={closeLabel}><X size={16} /></BaseDialog.Close>
            </div>
          </div>
          <div data-slot="lightbox-stage">
            <button type="button" data-slot="button" data-variant="outline" data-size="icon" aria-label={previousLabel} onClick={() => go(index - 1)}><ChevronLeft size={16} /></button>
            {img && <img data-slot="lightbox-image" src={img.src} alt={img.alt} />}
            <button type="button" data-slot="button" data-variant="outline" data-size="icon" aria-label={nextLabel} onClick={() => go(index + 1)}><ChevronRight size={16} /></button>
          </div>
          <div data-slot="lightbox-thumbs">
            {images.map((im, i) => (
              <button key={im.src} type="button" data-slot="lightbox-thumb" data-active={i === index} aria-label={im.alt} onClick={() => go(i)}>
                <img src={im.thumb ?? im.src} alt="" />
              </button>
            ))}
          </div>
        </BaseDialog.Popup>
      </BaseDialog.Portal>
    </BaseDialog.Root>
  )
}

/** A grid of thumbnails that opens the Lightbox. */
export function LightboxGallery({ images, columns = 3, openLabel = (alt) => `Open ${alt}`, ...viewer }: { images: LightboxImage[]; columns?: number; openLabel?: (alt: string) => string } & Pick<LightboxProps, 'label' | 'closeLabel' | 'previousLabel' | 'nextLabel' | 'className'>) {
  const [open, setOpen] = React.useState(false)
  const [index, setIndex] = React.useState(0)
  return (
    <>
      <div style={{ display: 'grid', gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`, gap: 'var(--fp-space-2)' }}>
        {images.map((im, i) => (
          <button key={im.src} type="button" data-slot="lightbox-open" aria-label={openLabel(im.alt)} onClick={() => { setIndex(i); setOpen(true) }}>
            <span data-slot="image" data-ratio="square"><img data-slot="image-element" src={im.thumb ?? im.src} alt={im.alt} loading="lazy" /></span>
          </button>
        ))}
      </div>
      <Lightbox images={images} open={open} index={index} onOpenChange={setOpen} onIndexChange={setIndex} {...viewer} />
    </>
  )
}

import * as React from 'react'

export type MasonryKey = string | number
export type MasonryGap = number | Partial<Record<'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl', number>>

export type MasonryItem<T = unknown> = {
  key: MasonryKey
  data?: T
  height?: number
  column?: number
  children?: React.ReactNode
}

export type MasonryProps<T = unknown> = {
  items: MasonryItem<T>[]
  /** fixed column count, or a per-breakpoint map */
  columns?: number | Partial<Record<'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl', number>>
  /** gap between items: one value, a per-breakpoint map, or [horizontal, vertical] */
  gutter?: MasonryGap | [MasonryGap, MasonryGap]
  itemRender?: (item: MasonryItem<T>, index: number) => React.ReactNode
  /** called after distribution with each item's column index */
  onLayoutChange?: (layout: { key: MasonryKey; column: number }[]) => void
  /** re-measure when item heights change after mount */
  fresh?: boolean
  className?: string
  style?: React.CSSProperties
}

type Bp = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl'
const BREAKPOINTS: { bp: Bp; min: number }[] = [
  { bp: 'xxl', min: 1600 }, { bp: 'xl', min: 1200 }, { bp: 'lg', min: 992 },
  { bp: 'md', min: 768 }, { bp: 'sm', min: 576 }, { bp: 'xs', min: 0 },
]

function pick<T>(v: T | Partial<Record<Bp, T>> | undefined, width: number, fallback: T): T {
  if (v == null) return fallback
  if (typeof v !== 'object') return v as T
  const match = BREAKPOINTS.find((b) => width >= b.min)?.bp ?? 'xs'
  const map = v as Partial<Record<Bp, T>>
  // walk from the matched breakpoint up to larger ones, then down
  const order: Bp[] = ['xs', 'sm', 'md', 'lg', 'xl', 'xxl']
  const idx = order.indexOf(match)
  for (let i = idx; i >= 0; i--) {
    const val = map[order[i]]
    if (val != null) return val
  }
  for (let i = idx + 1; i < order.length; i++) {
    const val = map[order[i]]
    if (val != null) return val
  }
  return fallback
}

/**
 * Waterfall layout: items fill the shortest column, left to right.
 * Heights are measured before paint so the first paint is already correct.
 */
export function Masonry<T = unknown>({
  items,
  columns = 3,
  gutter = 0,
  itemRender,
  onLayoutChange,
  fresh = false,
  className,
  style,
}: MasonryProps<T>) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const probeRef = React.useRef<HTMLDivElement>(null)
  const [width, setWidth] = React.useState(0)
  const [viewport, setViewport] = React.useState(() => (typeof window === 'undefined' ? 1280 : window.innerWidth))
  const [heights, setHeights] = React.useState<Record<string, number>>({})

  React.useEffect(() => {
    if (typeof window === 'undefined') return
    const onResize = () => setViewport(window.innerWidth)
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [])

  // breakpoints follow the viewport (xs/sm/md…), column width follows the container
  const colCount = Math.max(1, Math.round(pick(columns, viewport, 3)))
  const [hGap, vGap] = React.useMemo(() => {
    if (Array.isArray(gutter)) {
      return [pick(gutter[0], viewport, 0), pick(gutter[1], viewport, 0)]
    }
    const g = pick(gutter, viewport, 0)
    return [g, g]
  }, [gutter, viewport])

  const colWidth = width > 0 ? Math.max(0, (width - hGap * (colCount - 1)) / colCount) : 0

  React.useLayoutEffect(() => {
    const host = hostRef.current
    if (!host) return
    const measure = () => setWidth(host.clientWidth)
    measure()
    if (typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver(measure)
    ro.observe(host)
    return () => ro.disconnect()
  }, [])

  // measure item heights in a hidden single-column probe
  const layoutKey = items.map((i) => i.key).join('|')
  React.useLayoutEffect(() => {
    const probe = probeRef.current
    if (!probe || colWidth <= 0) return
    const next: Record<string, number> = {}
    items.forEach((item, i) => {
      const node = probe.querySelector<HTMLElement>(`[data-fp-probe="${i}"]`)
      next[String(item.key)] = item.height ?? (node?.offsetHeight ?? 0)
    })
    setHeights((prev) => {
      const same = Object.keys(next).every((k) => prev[k] === next[k]) && Object.keys(prev).length === Object.keys(next).length
      return same ? prev : next
    })
  }, [layoutKey, colWidth, items, fresh])

  const layout = React.useMemo(() => {
    const cols: MasonryItem<T>[][] = Array.from({ length: colCount }, () => [])
    const used = Array.from({ length: colCount }, () => 0)
    const assigned: { key: MasonryKey; column: number }[] = []
    items.forEach((item) => {
      let col: number
      if (item.column != null && item.column >= 0 && item.column < colCount) {
        col = item.column
      } else {
        col = used.indexOf(Math.min(...used))
      }
      cols[col].push(item)
      used[col] += (heights[String(item.key)] ?? item.height ?? 0) + vGap
      assigned.push({ key: item.key, column: col })
    })
    return { cols, assigned }
  }, [items, colCount, heights, vGap])

  const layoutSignature = layout.assigned.map((a) => `${a.key}:${a.column}`).join(',')
  React.useEffect(() => {
    onLayoutChange?.(layout.assigned)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [layoutSignature])

  const renderItem = (item: MasonryItem<T>, index: number) =>
    itemRender ? itemRender(item, index) : (item.children ?? null)

  return (
    <div ref={hostRef} data-slot="masonry" className={className} style={{ width: '100%', ...style }}>
      {/* hidden measurement pass — same width as a column, laid out before paint */}
      <div
        ref={probeRef}
        aria-hidden="true"
        style={{ position: 'absolute', width: colWidth || '100%', visibility: 'hidden', pointerEvents: 'none', left: -99999, top: 0 }}
      >
        {items.map((item, i) => (
          <div key={item.key} data-fp-probe={i}>{renderItem(item, i)}</div>
        ))}
      </div>

      <div style={{ display: 'flex', alignItems: 'flex-start', gap: hGap }}>
        {layout.cols.map((col, ci) => (
          <div key={ci} data-slot="masonry-column" style={{ flex: '1 1 0', minWidth: 0, display: 'flex', flexDirection: 'column', gap: vGap }}>
            {col.map((item) => {
              const index = items.indexOf(item)
              return (
                <div key={item.key} data-slot="masonry-item">{renderItem(item, index)}</div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

import { Menubar as BaseMenubar } from '@base-ui/react/menubar'
import { Menu as BaseMenu } from '@base-ui/react/menu'
import { MenuEntries, type MenuEntry } from '@/components/ui/context-menu'

export type MenubarMenu = { label: string; entries: MenuEntry[] }

/** A desktop-style menu bar: File, Edit, View … Hovering moves between open menus. */
