}

import * as React from 'react'
import { UserRound } from 'lucide-react'
import { Avatar } from '@/components/ui/avatar'

export type MessageProps = Omit<React.ComponentProps<'div'>, 'role'> & {
  /** Who wrote it. The user's message sits on the right with a grey ground; the assistant's is plain text on the left. */
  role?: 'user' | 'assistant'
  /** Name for the default avatar (its first two letters). Without it the assistant shows "AI" and the user a person icon. */
  name?: string
  /** Replaces the default avatar. */
  avatar?: React.ReactNode
}

/**
 * One turn of a conversation: an avatar and the content. The content can be text or anything
 * else, such as Thinking, ToolCall and a CodeBlock stacked in the order the assistant produced them.
 */
export function Message({ role = 'assistant', name, avatar, children, ...props }: MessageProps) {
  return (
    <div data-slot="message" data-role={role} {...props}>
      {avatar ?? (name || role === 'assistant'
        ? <Avatar size="sm" name={name ?? 'AI'} />
        // "You" in letters reads as "YO", so an unnamed user gets an icon; the title still says "You".
        : <Avatar size="sm" name="You"><UserRound size={16} aria-hidden="true" /></Avatar>)}
      <div data-slot="message-body">{children}</div>
    </div>
  )
}

import * as React from 'react'
import { Meter as BaseMeter } from '@base-ui/react/meter'

export type MeterProps = Omit<BaseMeter.Root.Props, 'className' | 'children'> & {
  label?: React.ReactNode
  /** Show the formatted value on the right. */
  showValue?: boolean
  size?: 'sm' | 'default' | 'lg'
  className?: string
}

/**
 * A value inside a known range, such as disk used or a score. Use Progress for a task that
 * finishes. Pass `aria-label` when there is no visible `label`. `format` takes
 * `Intl.NumberFormat` options, e.g. `{ style: 'percent' }` with min 0 and max 1.
 */
export function Meter({ label, showValue, size = 'default', className, ...props }: MeterProps) {
  return (
    <BaseMeter.Root data-slot="meter" data-size={size} className={className} {...props}>
      {(label || showValue) && (
        <div data-slot="meter-header">
          {label && <BaseMeter.Label data-slot="meter-label">{label}</BaseMeter.Label>}
          {showValue && <BaseMeter.Value data-slot="meter-value" />}
        </div>
      )}
      <BaseMeter.Track data-slot="meter-track">
        <BaseMeter.Indicator data-slot="meter-bar" />
      </BaseMeter.Track>
    </BaseMeter.Root>
  )
}

import * as React from 'react'
import { Combobox as BaseCombobox } from '@base-ui/react/combobox'
import { Check, X } from 'lucide-react'

export type MultiSelectOption = { value: string; label: string }

export type MultiSelectProps = {
  options: MultiSelectOption[]
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  placeholder?: string
  emptyText?: string
  disabled?: boolean
  'aria-label'?: string
  'aria-labelledby'?: string
  /** Form field name, submitted with the surrounding <form>. */
  name?: string
  required?: boolean
  id?: string
  className?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  onInputValueChange?: (text: string) => void
  /** Accessible name of each chip's remove button, for localized products. */
  removeLabel?: (label: string) => string
}

/** Pick several options; each choice becomes an ink chip (Tokenizer). Backspace removes the last. */
export function MultiSelect({ options, value, defaultValue, onValueChange, placeholder = 'Add…', emptyText = 'No matches', disabled, 'aria-label': ariaLabel, 'aria-labelledby': labelledBy, name, required, id, className, open, defaultOpen, onOpenChange, onInputValueChange, removeLabel = (label) => `Remove ${label}` }: MultiSelectProps) {
  const pick = (vs?: string[]) => (vs === undefined ? undefined : options.filter((o) => vs.includes(o.value)))
  const anchor = React.useRef<HTMLDivElement>(null)
  return (
    <BaseCombobox.Root
      multiple
      items={options}
      value={pick(value)}
      defaultValue={pick(defaultValue)}
      itemToStringLabel={(o: MultiSelectOption) => o.label}
      isItemEqualToValue={(a: MultiSelectOption, b: MultiSelectOption) => a.value === b.value}
      onValueChange={(os) => onValueChange?.((os as MultiSelectOption[]).map((o) => o.value))}
      disabled={disabled}
      name={name}
      required={required}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      onInputValueChange={onInputValueChange}
    >
      <div data-slot="combobox" className={className}>
        <BaseCombobox.Chips data-slot="combobox-control" data-multiple="true" ref={anchor}>
          <BaseCombobox.Value>
            {(selected: MultiSelectOption[]) => (
              <>
                {selected.map((o) => (
                  <BaseCombobox.Chip key={o.value} data-slot="combobox-chip" aria-label={o.label}>
                    {o.label}
                    <BaseCombobox.ChipRemove data-slot="combobox-chip-remove" aria-label={removeLabel(o.label)}><X size={12} /></BaseCombobox.ChipRemove>
                  </BaseCombobox.Chip>
                ))}
                <BaseCombobox.Input data-slot="combobox-input" id={id} placeholder={selected.length ? '' : placeholder} aria-label={ariaLabel} aria-labelledby={labelledBy} />
              </>
            )}
          </BaseCombobox.Value>
        </BaseCombobox.Chips>
      </div>
      <BaseCombobox.Portal>
        <BaseCombobox.Positioner data-slot="combobox-positioner" sideOffset={4} anchor={anchor}>
          <BaseCombobox.Popup data-slot="combobox-content">
            <BaseCombobox.Empty data-slot="combobox-empty">{emptyText}</BaseCombobox.Empty>
            <BaseCombobox.List>
              {(o: MultiSelectOption) => (
                <BaseCombobox.Item key={o.value} value={o} data-slot="combobox-item">
                  {o.label}
                  <BaseCombobox.ItemIndicator><Check size={16} /></BaseCombobox.ItemIndicator>
                </BaseCombobox.Item>
              )}
            </BaseCombobox.List>
          </BaseCombobox.Popup>
        </BaseCombobox.Positioner>
      </BaseCombobox.Portal>
    </BaseCombobox.Root>
  )
}

import { NumberField } from '@base-ui/react/number-field'
import { Minus, Plus } from 'lucide-react'

export type NumberInputProps = Omit<NumberField.Root.Props, 'className' | 'children' | 'render' | 'onValueChange'> & {
  onValueChange?: (value: number | null) => void
  /** sm 32 / md 40 / lg 48, same as Button. `default` is an alias of `md`. */
  size?: 'sm' | 'md' | 'default' | 'lg'
  className?: string
  'aria-label'?: string
  'aria-labelledby'?: string
  /** Accessible names of the stepper buttons, for localized products. */
  decrementLabel?: string
  incrementLabel?: string
}

/**
 * A number with − / + steppers. Arrow keys and the scroll wheel step too. Controlled (`value`)
 * or uncontrolled (`defaultValue`); Base UI root props (name, required, format, locale…) pass through.
 */
export function NumberInput({
  onValueChange, 'aria-label': ariaLabel, 'aria-labelledby': labelledBy, size = 'md',
  className, decrementLabel = 'Decrease', incrementLabel = 'Increase', ...props
}: NumberInputProps) {
  return (
    <NumberField.Root {...props} onValueChange={(v) => onValueChange?.(v)}>
      <NumberField.Group data-slot="number-input" data-size={size === 'default' ? 'md' : size} className={className}>
        <NumberField.Decrement data-slot="number-input-step" aria-label={decrementLabel}><Minus size={16} /></NumberField.Decrement>
        <NumberField.Input data-slot="number-input-field" aria-label={ariaLabel} aria-labelledby={labelledBy} />
        <NumberField.Increment data-slot="number-input-step" aria-label={incrementLabel}><Plus size={16} /></NumberField.Increment>
      </NumberField.Group>
    </NumberField.Root>
  )
}

import * as React from 'react'
import { OTPField as BaseOTPField } from '@base-ui/react/otp-field'
import { VisuallyHidden } from '@/components/ui/visually-hidden'

export type OtpFieldProps = Omit<BaseOTPField.Root.Props, 'className' | 'children' | 'length'> & {
  /** Number of boxes. Default 6. */
  length?: number
  /** Print a dash after this many boxes, e.g. 3 gives `123-456`. */
  groupSize?: number
  size?: 'sm' | 'md' | 'default' | 'lg'
  invalid?: boolean
  className?: string
  /** Accessible name for box `index` (0-based). Default "Character 2 of 6". */
  getInputLabel?: (index: number, length: number) => string
}

/**
 * A row of single-character boxes for one-time codes. Typing moves forward, Backspace moves back
 * and pasting a whole code fills every box. Controlled (`value` + `onValueChange`) or uncontrolled
 * (`defaultValue`). `onValueComplete` fires once every box is filled. Name the group with a Field
 * label or `aria-label`.
 */
export function OtpField({ length = 6, groupSize, size = 'md', invalid, className, getInputLabel, ...props }: OtpFieldProps) {
  // Base UI ignores aria-label on the first box (a screen reader lands there first), so the name is
  // carried by a hidden text node that the first box points to.
  const ariaLabel = props['aria-label']
  const nameId = React.useId()
  const sz = size === 'default' ? 'md' : size
  const label = getInputLabel ?? ((i: number, n: number) => `Character ${i + 1} of ${n}`)
  const items: React.ReactNode[] = []
  for (let i = 0; i < length; i++) {
    if (groupSize && i > 0 && i % groupSize === 0) items.push(<span key={`s${i}`} data-slot="otp-separator" aria-hidden="true" />)
    items.push(
      <BaseOTPField.Input
        key={i}
        data-slot="otp-input"
        aria-label={i === 0 ? undefined : label(i, length)}
        aria-labelledby={i === 0 && ariaLabel ? nameId : undefined}
        aria-invalid={invalid || undefined}
      />,
    )
  }
  return (
    <BaseOTPField.Root data-slot="otp-field" data-size={sz} length={length} className={className} {...props}>
      {ariaLabel && <VisuallyHidden id={nameId}>{ariaLabel}</VisuallyHidden>}
      {items}
    </BaseOTPField.Root>
  )
}

import * as React from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export type PaginationProps = Omit<React.HTMLAttributes<HTMLElement>, 'defaultValue' | 'onChange'> & {
  total: number
  pageSize?: number
  /** Controlled page (1-based). Pair with onValueChange. */
  value?: number
  defaultValue?: number
  onValueChange?: (page: number) => void
  siblingCount?: number
  /** Accessible names, for localized products. */
  label?: string
  previousLabel?: string
  nextLabel?: string
}

export function Pagination({ total, pageSize = 10, value, defaultValue = 1, onValueChange, siblingCount = 1, label = 'Pagination', previousLabel = 'Previous page', nextLabel = 'Next page', ...props }: PaginationProps) {
  const [internal, setInternal] = React.useState(defaultValue)
  const page = value !== undefined ? value : internal
  const pageCount = Math.max(1, Math.ceil(total / pageSize))
  const go = (p: number) => {
    const next = Math.max(1, Math.min(pageCount, p))
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }
  const pages = React.useMemo(() => {
    const set = new Set<number>([1, pageCount])
    for (let i = page - siblingCount; i <= page + siblingCount; i++) if (i >= 1 && i <= pageCount) set.add(i)
    const sorted = [...set].sort((a, b) => a - b)
    const out: (number | 'ellipsis')[] = []
    sorted.forEach((p, i) => {
      if (i > 0 && p - sorted[i - 1] > 1) out.push('ellipsis')
      out.push(p)
    })
    return out
  }, [page, pageCount, siblingCount])

  return (
    <nav data-slot="pagination" aria-label={label} {...props}>
      <button data-slot="pagination-btn" data-nav="true" type="button" disabled={page <= 1} onClick={() => go(page - 1)} aria-label={previousLabel}>
        <ChevronLeft size={16} />
      </button>
      {pages.map((p, i) => p === 'ellipsis'
        ? <span data-slot="pagination-ellipsis" key={`e${i}`}>···</span>
        : <button data-slot="pagination-btn" data-active={p === page} type="button" key={p} onClick={() => go(p)}>{p}</button>)}
      <button data-slot="pagination-btn" data-nav="true" type="button" disabled={page >= pageCount} onClick={() => go(page + 1)} aria-label={nextLabel}>
        <ChevronRight size={16} />
      </button>
    </nav>
  )
}

import * as React from 'react'
import { Popover as BasePopover } from '@base-ui/react/popover'

/** Controlled (`open` + `onOpenChange`) or uncontrolled (`defaultOpen`). */
export function Popover({ children, ...props }: Omit<BasePopover.Root.Props, 'children'> & { children?: React.ReactNode }) {
  return (
    <BasePopover.Root {...props}>
      <div data-slot="popover">{children}</div>
    </BasePopover.Root>
  )
}

export type PopoverTriggerProps = Omit<BasePopover.Trigger.Props, 'className'> & {
  size?: 'sm' | 'md' | 'default' | 'lg'
  variant?: 'default' | 'secondary' | 'outline' | 'ghost'
  className?: string
}

export function PopoverTrigger({ size = 'md', variant = 'outline', className, render, ...props }: PopoverTriggerProps) {
  const own = render === undefined
  return (
    <BasePopover.Trigger
      className={className}
      render={render}
      {...(own ? { 'data-slot': 'button', 'data-variant': variant, 'data-size': size === 'md' ? 'default' : size } : {})}
      {...props}
    />
  )
}

export type PopoverContentProps = Omit<BasePopover.Popup.Props, 'className' | 'title'> & {
  title?: string
  side?: 'top' | 'bottom' | 'left' | 'right'
  align?: 'start' | 'center' | 'end'
  sideOffset?: number
  className?: string
}

export function PopoverContent({ title, children, side = 'bottom', align, sideOffset, className, ...props }: PopoverContentProps) {
  return (
    <BasePopover.Portal>
      <BasePopover.Positioner data-slot="popover-positioner" side={side} align={align} sideOffset={sideOffset}>
        <BasePopover.Popup data-slot="popover-content" data-side={side} className={className} {...props}>
          {title && <BasePopover.Title render={<div data-slot="popover-title">{title}</div>} />}
          <div data-slot="popover-body">{children}</div>
        </BasePopover.Popup>
      </BasePopover.Positioner>
    </BasePopover.Portal>
  )
}

import * as React from 'react'

/** A plain 1px horizontal rule. For a labelled or vertical rule, use Divider. */
export function Separator(props: React.HTMLAttributes<HTMLHRElement>) { return <hr data-slot="separator" {...props} /> }
/** The grey line above a heading. */
export function Kicker(props: React.HTMLAttributes<HTMLDivElement>) { return <div data-slot="kicker" {...props} /> }

import * as React from 'react'
import { Progress as BaseProgress } from '@base-ui/react/progress'

export type ProgressProps = Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> & {
  value: number
  max?: number
  label?: React.ReactNode
  showValue?: boolean
  size?: 'sm' | 'default' | 'lg'
}

/** Pass `aria-label` when there is no visible `label`, so the bar still has an accessible name. */
export function Progress({ value, max = 100, label, showValue, size = 'default', ...rest }: ProgressProps) {
  const total = Number.isFinite(max) && max > 0 ? max : 1
  const current = Number.isFinite(value) ? Math.max(0, Math.min(total, value)) : 0
  const pct = (current / total) * 100
  return (
    <BaseProgress.Root value={current} max={total} data-slot="progress" data-size={size} {...rest}>
      {(label || showValue) && (
        <div data-slot="progress-header">
          {label && <BaseProgress.Label data-slot="progress-label">{label}</BaseProgress.Label>}
          {showValue && <span data-slot="progress-value">{Math.round(pct)}%</span>}
        </div>
      )}
      <BaseProgress.Track data-slot="progress-track">
        <BaseProgress.Indicator data-slot="progress-bar" style={{ width: `${pct}%` }} />
      </BaseProgress.Track>
    </BaseProgress.Root>
  )
}

import * as React from 'react'
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group'
import { Radio } from '@base-ui/react/radio'

type RadioItem = { value: string; label: React.ReactNode; disabled?: boolean }
export type RadioGroupProps = Omit<BaseRadioGroup.Props, 'className' | 'children' | 'render' | 'onValueChange'> & {
  options: RadioItem[]
  onValueChange?: (value: string) => void
  className?: string
}

/** Controlled (`value`) or uncontrolled (`defaultValue`). Group props such as name, required, disabled and aria-* pass through. */
export function RadioGroup({ options, onValueChange, className, name, ...props }: RadioGroupProps) {
  // useId keeps the generated name identical on the server and the client.
  const generated = React.useId()
  return (
    <BaseRadioGroup
      data-slot="radio-group"
      name={name ?? `radio-${generated}`}
      className={className}
      onValueChange={(nextValue) => onValueChange?.(nextValue as string)}
      {...props}
    >
      {options.map((o) => (
        <label key={o.value} data-slot="radio" data-disabled={o.disabled ? 'true' : 'false'}>
          <Radio.Root
            value={o.value}
            disabled={o.disabled}
            aria-label={typeof o.label === 'string' ? o.label : undefined}
          >
            <Radio.Indicator
              keepMounted
              data-slot="radio-circle"
              render={(indicatorProps, state) => (
                <span {...indicatorProps} data-state={state.checked ? 'checked' : 'unchecked'}>
                  {state.checked && <span data-slot="radio-dot" />}
                </span>
              )}
            />
          </Radio.Root>
          <span data-slot="radio-label">{o.label}</span>
        </label>
      ))}
    </BaseRadioGroup>
  )
}

import { useEffect, useRef, type ComponentPropsWithoutRef } from 'react'

/** Progressive enhancement: SSR and unsupported clients keep all content readable. */
export function RevealGroup({ children, ...props }: ComponentPropsWithoutRef<'div'>) {
  const root = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const container = root.current
    const preference = matchMedia('(prefers-reduced-motion: reduce)')
    if (!container || preference.matches || typeof IntersectionObserver === 'undefined') return
    const targets = Array.from(
      container.querySelectorAll<HTMLElement>('[data-reveal="scroll"]'),
    ).filter((target) => target.closest('[data-reveal-group]') === container)
    let observer: IntersectionObserver | undefined
    const show = (target: HTMLElement) => {
      if (target.dataset.revealState !== 'pending') return
      target.dataset.revealState = 'shown'
      observer?.unobserve(target)
    }
    const restore = () => {
      observer?.disconnect()
      targets.forEach((target) => target.removeAttribute('data-reveal-state'))
    }
    const focus = (event: FocusEvent) => {
      if (!(event.target instanceof Element)) return
      const target = event.target.closest<HTMLElement>('[data-reveal="scroll"]')
      if (target && targets.includes(target)) show(target)
    }
    try {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) show(entry.target as HTMLElement)
          })
        },
        { rootMargin: '0px 0px -24px 0px', threshold: 0 },
      )
      targets.forEach((target) => {
        // Never hide content already visible, above the viewport, or containing focus.
        if (
          target.getBoundingClientRect().top < innerHeight ||
          target.contains(document.activeElement)
        )
          return
        target.dataset.revealState = 'pending'
        observer?.observe(target)
      })
    } catch {
      restore()
    }
    container.addEventListener('focusin', focus)
    preference.addEventListener('change', restore)
    return () => {
      restore()
      container.removeEventListener('focusin', focus)
      preference.removeEventListener('change', restore)
    }
  }, [])
  return (
    <div {...props} ref={root} data-reveal-group="">
      {children}
    </div>
  )
}

import * as React from 'react'
import { ScrollArea as BaseScrollArea } from '@base-ui/react/scroll-area'

/** A scroll container with a thin square scrollbar that appears on hover. */
