import * as React from 'react'
import { RotateCcw, Square } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { StatusDot } from '@/components/ui/status-dot'
import { Message } from '@/components/ui/message'
import { Thinking } from '@/components/ui/thinking'
import { ToolCall } from '@/components/ui/tool-call'
import { TaskList, type Task } from '@/components/ui/task-list'
import { Approval } from '@/components/ui/approval'
import { DiffValue } from '@/components/ui/diff'
import { Citation, Sources } from '@/components/ui/sources'

export type Agent01Props = {
  /** What the user asked the agent to do. */
  goal?: string
  /**
   * Runs the destructive step after the user approves it. While the promise is pending the
   * delete step shows as running; if it rejects, the step fails and the run stops.
   * Without it the block waits a moment and pretends the delete worked.
   */
  onApprove?: () => Promise<void> | void
  /** Called when the user denies the step. Nothing is deleted. */
  onDeny?: () => void
  /** Milliseconds between the simulated steps before and after the approval. Default 700. */
  stepDelay?: number
}

// The run has six steps; each index is one moment of the run.
//   0 reading drafts · 1 checking payments · 2 waiting for approval · 3 deleting · 4 summarizing · 5 done
type Outcome = 'running' | 'denied' | 'stopped' | 'failed'

const PLAN = ['Find draft orders older than 30 days', 'Check none of them has a payment', 'Ask before deleting', 'Delete the drafts', 'Write a summary']

/**
 * Agent run: the agent works through a plan, stops to ask before it deletes anything, then
 * reports back with its sources. The log on the left shows each step as it happens; the plan on
 * the right shows where the run is. The plan moves above the log below 720px of the block's width.
 */
export function Agent01({ goal = 'Clean up draft orders older than 30 days.', onApprove, onDeny, stepDelay = 700 }: Agent01Props) {
  const [step, setStep] = React.useState(0)
  const [outcome, setOutcome] = React.useState<Outcome>('running')
  const [decision, setDecision] = React.useState<'pending' | 'approved' | 'denied'>('pending')

  // Advance the simulated steps. The run halts at the approval (step 2) and while the approved
  // delete is in progress (step 3 is advanced by approve()).
  React.useEffect(() => {
    if (outcome !== 'running' || step === 2 || step === 3 || step >= 5) return
    const t = window.setTimeout(() => setStep((s) => s + 1), stepDelay)
    return () => window.clearTimeout(t)
  }, [step, outcome, stepDelay])

  const approve = async () => {
    if (outcome !== 'running') return
    setDecision('approved')
    setStep(3)
    try {
      if (onApprove) await onApprove()
      else await new Promise((r) => window.setTimeout(r, stepDelay))
      setStep((s) => (s === 3 ? 4 : s))
    } catch {
      setOutcome((o) => (o === 'running' ? 'failed' : o))
    }
  }
  const deny = () => {
    if (outcome !== 'running') return
    setDecision('denied')
    setOutcome('denied')
    onDeny?.()
  }
  const restart = () => { setStep(0); setOutcome('running'); setDecision('pending') }

  const finished = step >= 5 || outcome !== 'running'
  const tasks: Task[] = PLAN.map((title, i) => {
    const id = String(i + 1)
    if (i < step) return { id, title, status: 'done' }
    if (i > step) return { id, title, status: 'queued', detail: outcome !== 'running' ? 'Skipped' : undefined }
    if (outcome === 'denied') return { id, title, status: 'failed', detail: 'Denied' }
    if (outcome === 'stopped') return { id, title, status: 'failed', detail: 'Stopped' }
    if (outcome === 'failed') return { id, title, status: 'failed', detail: 'Failed' }
    return { id, title, status: 'running', detail: i === 2 ? 'Waiting for you' : undefined }
  })

  const state =
    step >= 5 ? { dot: 'success' as const, text: 'Done' }
      : outcome === 'running' ? (step === 2 ? { dot: 'idle' as const, text: 'Waiting for approval' } : { dot: 'default' as const, text: 'Running' })
        : outcome === 'failed' ? { dot: 'danger' as const, text: 'Failed' }
          : { dot: 'idle' as const, text: outcome === 'denied' ? 'Denied' : 'Stopped' }

  return (
    <div data-slot="block-agent">
      <div data-slot="block-agent-layout">
        <header data-slot="block-agent-header">
          <div style={{ minWidth: 0 }}>
            <h2 style={{ fontSize: 'var(--fp-text-lg)', fontWeight: 'var(--fp-weight-semibold)', margin: 0 }}>Agent run</h2>
            <StatusDot status={state.dot} aria-live="polite">{state.text}</StatusDot>
          </div>
          {finished ? (
            <Button size="sm" variant="outline" onClick={restart}><RotateCcw size={16} /> Run again</Button>
          ) : (
            // A delete in progress cannot be taken back halfway, so Stop waits until it is over.
            <Button size="sm" variant="outline" disabled={step === 3} onClick={() => setOutcome('stopped')}><Square size={16} /> Stop</Button>
          )}
        </header>

        <aside data-slot="block-agent-plan" aria-label="Plan">
          <div className="fp-label">Plan</div>
          <TaskList aria-label="Plan steps" tasks={tasks} />
        </aside>

        <div data-slot="block-agent-log" role="log" aria-label="Run log">
          <Message role="user">{goal}</Message>
          <Message>
            {step === 0 && outcome === 'running' ? (
              <Thinking status="thinking"><span>Looking for drafts created more than 30 days ago.</span></Thinking>
            ) : (
              <Thinking duration={2}>
                <span>Looking for drafts created more than 30 days ago.</span>
                <span>A draft with a payment attached is a real order in progress, so those must stay.</span>
              </Thinking>
            )}
            {step >= 1 && <ToolCall name="Searched orders" detail="12 drafts" />}
            {step >= 2 && <ToolCall name="Checked payments" detail="0 paid" />}
            {step >= 2 && (
              <Approval
                title="Delete 12 draft orders?"
                description="All 12 are older than 30 days and none has a payment. Deleted drafts cannot be restored."
                // Stopped before anyone answered: the question closes without a decision.
                status={outcome === 'stopped' && decision === 'pending' ? 'denied' : decision}
                deniedLabel={outcome === 'stopped' && decision === 'pending' ? 'Not answered' : 'Denied'}
                onApprove={approve}
                onDeny={deny}
              />
            )}
            {step >= 3 && (decision === 'approved') && (
              <ToolCall
                status={step === 3 ? (outcome === 'failed' ? 'error' : 'running') : 'done'}
                name={step === 3 ? (outcome === 'failed' ? 'Delete drafts' : 'Deleting drafts') : 'Deleted drafts'}
                detail="12 orders"
              />
            )}
            {step >= 5 && (
              <>
                <p style={{ margin: 0 }}>
                  Done. I deleted the 12 drafts older than 30 days <Citation n={1} title="Orders export" />; none had a
                  payment <Citation n={2} title="Payments ledger" />. Open drafts: <DiffValue from="31" to="19" />.
                </p>
                <Sources items={[{ title: 'Orders export', note: 'status = draft, created before 30 days ago' }, { title: 'Payments ledger', note: '0 matches for the 12 order ids' }]} />
              </>
            )}
            {outcome === 'denied' && <p style={{ margin: 0 }}>Understood. Nothing was deleted; the 12 drafts are still in the list.</p>}
            {outcome === 'stopped' && <p style={{ margin: 0 }}>Stopped. Nothing after this point ran.</p>}
            {outcome === 'failed' && <p style={{ margin: 0 }}>The delete did not go through, so the drafts are unchanged. Try again later.</p>}
          </Message>
        </div>
      </div>
    </div>
  )
}

import * as React from 'react'
import { MessageSquare, Paperclip, Plus } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Kbd } from '@/components/ui/kbd'
import { Message } from '@/components/ui/message'
import { Thinking } from '@/components/ui/thinking'
import { Composer } from '@/components/ui/composer'
import { Sidebar, SidebarSection, SidebarItem } from '@/components/ui/sidebar'

export type ChatMessage = { id: string; role: 'user' | 'assistant'; content: React.ReactNode }

export type Chat01Props = {
  initialMessages?: ChatMessage[]
  /**
   * Produce the reply to `text`. Return the reply content; it is shown when the promise resolves.
   * `signal` aborts when the user presses Stop. Without it the block echoes a canned reply.
   */
  onSend?: (text: string, signal: AbortSignal) => Promise<React.ReactNode>
  conversations?: string[]
}

const echo = (text: string, signal: AbortSignal) =>
  new Promise<React.ReactNode>((resolve, reject) => {
    const t = window.setTimeout(() => resolve(`You asked: “${text}”. Connect onSend to your model to answer for real.`), 1200)
    signal.addEventListener('abort', () => { window.clearTimeout(t); reject(new DOMException('Aborted', 'AbortError')) })
  })

let seq = 0
const nextId = () => `m${++seq}`

/**
 * Assistant screen: a conversation list, the messages, and a Composer that sends with Enter and
 * stops a running reply. The conversation list folds away below 720px of its own width.
 */
export function Chat01({ initialMessages = [], onSend = echo, conversations = ['Restock plan', 'Return policy copy', 'Q4 price check'] }: Chat01Props) {
  const [messages, setMessages] = React.useState(initialMessages)
  const [active, setActive] = React.useState(conversations[0])
  const [pending, setPending] = React.useState<AbortController | null>(null)
  const end = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => { end.current?.scrollIntoView?.({ block: 'nearest' }) }, [messages, pending])

  const send = async (text: string) => {
    setMessages((m) => [...m, { id: nextId(), role: 'user', content: text }])
    const ctrl = new AbortController()
    setPending(ctrl)
    try {
      const reply = await onSend(text, ctrl.signal)
      if (!ctrl.signal.aborted) setMessages((m) => [...m, { id: nextId(), role: 'assistant', content: reply }])
    } catch {
      if (!ctrl.signal.aborted) setMessages((m) => [...m, { id: nextId(), role: 'assistant', content: 'Something went wrong. Try again.' }])
    } finally {
      setPending((p) => (p === ctrl ? null : p))
    }
  }

  return (
    <div data-slot="block-chat">
      <div data-slot="block-chat-layout">
        <Sidebar data-block-chat-list="" aria-label="Conversations">
          <div style={{ padding: 'var(--fp-space-3)' }}>
            <Button size="sm" variant="outline" style={{ width: '100%' }} onClick={() => { pending?.abort(); setMessages([]) }}><Plus size={16} /> New chat</Button>
          </div>
          <SidebarSection label="Recent">
            {conversations.map((c) => <SidebarItem key={c} active={c === active} icon={<MessageSquare size={16} />} onClick={() => setActive(c)}>{c}</SidebarItem>)}
          </SidebarSection>
        </Sidebar>
        <div data-slot="block-chat-main">
          <div data-slot="block-chat-log" role="log" aria-label="Messages" aria-live="polite">
            {messages.length === 0 && !pending && (
              <p style={{ margin: 'auto', color: 'var(--fp-muted)', fontSize: 'var(--fp-text-sm)' }}>Ask about stock, orders or customers.</p>
            )}
            {messages.map((m) => <Message key={m.id} role={m.role}>{m.content}</Message>)}
            {pending && <Message role="assistant"><Thinking status="thinking" /></Message>}
            <div ref={end} />
          </div>
          <div data-slot="block-chat-input">
            <Composer
              placeholder="Ask anything"
              loading={pending != null}
              onStop={() => { pending?.abort(); setPending(null) }}
              onSubmit={send}
              leading={<span style={{ display: 'inline-flex', alignItems: 'center', gap: 'var(--fp-space-2)' }}><Kbd>⏎</Kbd> send · <Kbd>⇧⏎</Kbd> new line</span>}
              actions={<Button size="icon" variant="ghost" aria-label="Attach file"><Paperclip size={16} /></Button>}
            />
          </div>
        </div>
      </div>
    </div>
  )
}

import * as React from 'react'
import { Search, Trash2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { ChipGroup } from '@/components/ui/chip-group'
import { AlertDialog } from '@/components/ui/alert-dialog'
import { Empty } from '@/components/ui/empty'
import { DataTable, type DataTableColumn } from '@/components/ui/data-table'
import { InputGroup, InputGroupAddon, InputGroupInput } from '@/components/ui/input-group'

export type Order = { id: string; customer: string; status: 'Paid' | 'Pending' | 'Refunded'; total: number; date: string }

const SAMPLE: Order[] = [
  { id: 'A-1042', customer: 'Lena Fischer', status: 'Paid', total: 1299, date: '2025-05-02' },
  { id: 'A-1041', customer: 'Tomás Ruiz', status: 'Pending', total: 499, date: '2025-05-02' },
  { id: 'A-1040', customer: 'Mei Chen', status: 'Paid', total: 2398, date: '2025-05-01' },
  { id: 'A-1039', customer: 'Noah Smith', status: 'Refunded', total: 199, date: '2025-04-30' },
  { id: 'A-1038', customer: 'Aiko Tanaka', status: 'Paid', total: 749, date: '2025-04-30' },
  { id: 'A-1037', customer: 'Omar Haddad', status: 'Pending', total: 899, date: '2025-04-29' },
  { id: 'A-1036', customer: 'Sara Lind', status: 'Paid', total: 599, date: '2025-04-28' },
  { id: 'A-1035', customer: 'Ravi Patel', status: 'Paid', total: 1498, date: '2025-04-27' },
]

const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'CNY', maximumFractionDigits: 0 })
const day = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' })

const columns: DataTableColumn<Order>[] = [
  { key: 'id', header: 'Order', sortable: true, cell: (o) => <span className="fp-num">{o.id}</span> },
  { key: 'customer', header: 'Customer', sortable: true },
  { key: 'status', header: 'Status', cell: (o) => <Badge variant={o.status === 'Paid' ? 'default' : 'outline'}>{o.status}</Badge> },
  { key: 'date', header: 'Date', sortable: true, cell: (o) => day.format(new Date(o.date)) },
  { key: 'total', header: 'Total', sortable: true, align: 'end', cell: (o) => <span className="fp-num">{money.format(o.total)}</span> },
]

export type DataTable01Props = {
  orders?: Order[]
  /** Called with the ids the user confirmed for deletion. The block removes them from its own list. */
  onDelete?: (ids: string[]) => void
}

/**
 * Orders list: search, status chips with counts, a sortable table with selection and paging,
 * and a confirmed bulk delete. Everything runs on the array in memory; swap the filter for a
 * request when the list lives on a server.
 */
export function DataTable01({ orders = SAMPLE, onDelete }: DataTable01Props) {
  const [rows, setRows] = React.useState(orders)
  const [query, setQuery] = React.useState('')
  const [status, setStatus] = React.useState('All')
  const [selected, setSelected] = React.useState<string[]>([])
  const [page, setPage] = React.useState(1)

  const q = query.trim().toLowerCase()
  const matches = rows.filter((o) => !q || o.customer.toLowerCase().includes(q) || o.id.toLowerCase().includes(q))
  const shown = matches.filter((o) => status === 'All' || o.status === status)
  const count = (s: string) => matches.filter((o) => s === 'All' || o.status === s).length
  const filter = (fn: () => void) => { fn(); setPage(1) }

  const remove = () => {
    onDelete?.(selected)
    setRows(rows.filter((o) => !selected.includes(o.id)))
    setSelected([])
  }

  return (
    <div data-slot="block-data-table">
      <div data-slot="block-data-table-layout">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--fp-space-3)', flexWrap: 'wrap' }}>
          <h2 style={{ fontSize: 'var(--fp-text-lg)', fontWeight: 'var(--fp-weight-semibold)', letterSpacing: 'var(--fp-tracking-display)', margin: 0 }}>Orders</h2>
          <div style={{ width: 'min(100%, 280px)' }}>
            <InputGroup size="sm">
              <InputGroupAddon aria-hidden="true"><Search size={16} /></InputGroupAddon>
              <InputGroupInput aria-label="Search orders" placeholder="Search by name or order" value={query} onChange={(e) => filter(() => setQuery(e.target.value))} />
            </InputGroup>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--fp-space-3)', flexWrap: 'wrap', minHeight: 'var(--fp-control-sm)' }}>
          <ChipGroup
            aria-label="Status"
            size="sm"
            value={status}
            onValueChange={(v) => filter(() => setStatus(v))}
            options={['All', 'Paid', 'Pending', 'Refunded'].map((s) => ({ value: s, label: s, count: count(s) }))}
          />
          {selected.length > 0 && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--fp-space-2)' }}>
              <span style={{ fontSize: 'var(--fp-text-sm)', color: 'var(--fp-muted)' }} aria-live="polite">{selected.length} selected</span>
              <AlertDialog
                danger
                trigger={<Button size="sm" variant="outline"><Trash2 size={16} /> Delete</Button>}
                title={`Delete ${selected.length} ${selected.length === 1 ? 'order' : 'orders'}?`}
                description="They are removed from this list. This cannot be undone."
                confirmLabel="Delete"
                onConfirm={remove}
              />
            </div>
          )}
        </div>

        <DataTable
          aria-label="Orders"
          columns={columns}
          data={shown}
          getRowId={(o) => o.id}
          defaultSort={{ key: 'date', direction: 'desc' }}
          selectable
          selected={selected}
          onSelectedChange={setSelected}
          selectRowLabel={(o) => `Select order ${o.id}`}
          pageSize={5}
          page={page}
          onPageChange={setPage}
          empty={
            <Empty
              title="No matching orders"
              description="Try another name, or clear the filters."
              action={<Button size="sm" variant="outline" onClick={() => filter(() => { setQuery(''); setStatus('All') })}>Clear filters</Button>}
            />
          }
        />
      </div>
    </div>
  )
}

import * as React from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Checkbox } from '@/components/ui/checkbox'
import { Divider } from '@/components/ui/divider'
import { Field, FieldControl } from '@/components/ui/field'
import { Form } from '@/components/ui/form'

export type SignInValues = { email: string; password: string; remember: boolean }

export type Login01Props = {
  /** Brand name in the ink panel. */
  brand?: string
  headline?: React.ReactNode
  /**
   * Called with the values once the built-in checks pass. Resolve to sign in; resolve to a map of
   * errors by field name (`{ password: 'Wrong password' }`) to show them under the fields.
   */
  onSignIn?: (values: SignInValues) => Promise<Partial<Record<keyof SignInValues, string>> | void> | Partial<Record<keyof SignInValues, string>> | void
  /** A second way in, such as SSO or a magic link. Hidden when not given. */
  onOtherMethod?: () => void
  forgotHref?: string
}

/**
 * Sign-in screen: an ink panel with the brand on one side, the form on the other. Below 640px of
 * its own width the panel folds away. Email and password are checked on submit; server errors
 * returned from `onSignIn` show under the matching field and clear when the user edits it.
 */
export function Login01({ brand = 'Flatpack', headline = 'Build with clarity.', onSignIn, onOtherMethod, forgotHref = '#' }: Login01Props) {
  const [errors, setErrors] = React.useState<Record<string, string>>({})
  const [busy, setBusy] = React.useState(false)
  return (
    <div data-slot="block-login">
      <div data-slot="block-login-layout">
        <div data-slot="block-login-panel" className="fp-invert">
          <div style={{ fontWeight: 'var(--fp-weight-semibold)' }}>{brand}</div>
          <div style={{ fontSize: 'var(--fp-text-2xl)', fontWeight: 'var(--fp-weight-semibold)', letterSpacing: 'var(--fp-tracking-display)', lineHeight: 1.1 }}>{headline}</div>
        </div>
        <div data-slot="block-login-form">
          <h2 style={{ fontSize: 'var(--fp-text-lg)', fontWeight: 'var(--fp-weight-semibold)', margin: '0 0 var(--fp-space-2)' }}>Sign in</h2>
          <p style={{ margin: '0 0 var(--fp-space-5)', color: 'var(--fp-muted)', fontSize: 'var(--fp-text-sm)' }}>Welcome back. Enter your details.</p>
          <Form
            errors={errors}
            onFormSubmit={async (v) => {
              setBusy(true)
              try {
                const result = await onSignIn?.({ email: String(v.email ?? ''), password: String(v.password ?? ''), remember: Boolean(v.remember) })
                setErrors(result ?? {})
              } finally {
                setBusy(false)
              }
            }}
          >
            <Field label="Email" name="email" required>
              <FieldControl render={<Input type="email" required autoComplete="email" placeholder="you@example.com" />} />
            </Field>
            <Field label="Password" name="password" required>
              <FieldControl render={<Input type="password" required autoComplete="current-password" />} />
            </Field>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--fp-space-3)', flexWrap: 'wrap' }}>
              {/* Form only collects values from controls inside a Field. */}
              <Field name="remember"><Checkbox defaultChecked label="Remember me" /></Field>
              <a href={forgotHref} style={{ fontSize: 'var(--fp-text-sm)', color: 'var(--fp-ink)' }}>Forgot password?</a>
            </div>
            <Button type="submit" disabled={busy} style={{ width: '100%' }}>{busy ? 'Signing in…' : 'Sign in'}</Button>
            {onOtherMethod && (
              <>
                <Divider label="or" />
                <Button variant="outline" onClick={onOtherMethod} style={{ width: '100%' }}>Continue with SSO</Button>
              </>
            )}
          </Form>
        </div>
      </div>
    </div>
  )
}

import * as React from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Avatar } from '@/components/ui/avatar'
import { Switch } from '@/components/ui/switch'
import { Field, FieldControl, Fieldset } from '@/components/ui/field'
import { Form } from '@/components/ui/form'
import { Segmented } from '@/components/ui/segmented'
import { Sidebar, SidebarSection, SidebarItem } from '@/components/ui/sidebar'
import { toast } from '@/components/ui/toast'

export type Profile = { name: string; email: string; newsletter: boolean; digest: 'daily' | 'weekly' | 'never' }

export type Settings01Props = {
  defaultValue?: Profile
  /** Called with the values once the checks pass. Resolve to a map of errors by field name to show them. */
  onSave?: (profile: Profile) => Promise<Partial<Record<keyof Profile, string>> | void> | Partial<Record<keyof Profile, string>> | void
}

const SECTIONS = ['Profile', 'Notifications', 'Security', 'Billing'] as const

/**
 * Account settings: a section list beside a profile form. The form keeps its own draft, checks
 * name and email on save and confirms with a toast (mount `<Toaster />` once in the app).
 * Only Profile is built here; the other sections are placeholders for your own forms.
 */
export function Settings01({ defaultValue = { name: 'Alex Wang', email: 'alex@example.com', newsletter: true, digest: 'weekly' }, onSave }: Settings01Props) {
  const [section, setSection] = React.useState<(typeof SECTIONS)[number]>('Profile')
  const [digest, setDigest] = React.useState(defaultValue.digest)
  const [newsletter, setNewsletter] = React.useState(defaultValue.newsletter)
  const [name, setName] = React.useState(defaultValue.name)
  const [errors, setErrors] = React.useState<Record<string, string>>({})
  const [formKey, setFormKey] = React.useState(0)
  const digestId = React.useId()

  const reset = () => {
    setName(defaultValue.name)
    setNewsletter(defaultValue.newsletter)
    setDigest(defaultValue.digest)
    setErrors({})
    setFormKey((k) => k + 1)
  }

  return (
    <div data-slot="block-settings">
      <div data-slot="block-settings-layout">
        <Sidebar aria-label="Settings">
          <SidebarSection label="Account">
            {SECTIONS.map((s) => <SidebarItem key={s} active={s === section} onClick={() => setSection(s)}>{s}</SidebarItem>)}
          </SidebarSection>
        </Sidebar>
        <div style={{ flex: 1, minWidth: 0, maxWidth: 560 }}>
          <h2 style={{ fontSize: 'var(--fp-text-lg)', fontWeight: 'var(--fp-weight-semibold)', letterSpacing: 'var(--fp-tracking-display)', margin: '0 0 var(--fp-space-5)' }}>{section}</h2>
          {section !== 'Profile' ? (
            <p style={{ margin: 0, color: 'var(--fp-muted)', fontSize: 'var(--fp-text-sm)' }}>Put your {section.toLowerCase()} settings here.</p>
          ) : (
            <Form
              key={formKey}
              errors={errors}
              onFormSubmit={async (v) => {
                const profile: Profile = { name: String(v.name ?? ''), email: String(v.email ?? ''), newsletter, digest }
                const result = await onSave?.(profile)
                setErrors(result ?? {})
                if (!result || Object.keys(result).length === 0) toast({ title: 'Profile saved', type: 'success' })
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--fp-space-3)' }}>
                <Avatar name={name || '?'} size="lg" />
                <Button size="sm" variant="outline">Change photo</Button>
              </div>
              <div data-slot="block-settings-row">
                <Field label="Name" name="name" required>
                  <FieldControl render={<Input required defaultValue={defaultValue.name} autoComplete="name" onChange={(e) => setName(e.target.value)} />} />
                </Field>
                <Field label="Email" name="email" required description="Receipts and sign-in links go here.">
                  <FieldControl render={<Input type="email" required defaultValue={defaultValue.email} autoComplete="email" />} />
                </Field>
              </div>
              <Fieldset legend="Email updates">
                <Switch label="Product news" checked={newsletter} onCheckedChange={setNewsletter} />
                <div style={{ display: 'grid', gap: 'var(--fp-space-2)', justifyItems: 'start' }}>
                  <span style={{ fontSize: 'var(--fp-text-sm)', fontWeight: 'var(--fp-weight-medium)' }} id={digestId}>Activity digest</span>
                  <Segmented
                    aria-labelledby={digestId}
                    size="sm"
                    value={digest}
                    onValueChange={setDigest}
                    options={[{ value: 'daily', label: 'Daily' }, { value: 'weekly', label: 'Weekly' }, { value: 'never', label: 'Never' }]}
                  />
                </div>
              </Fieldset>
              <div style={{ display: 'flex', gap: 'var(--fp-space-2)' }}>
                <Button type="submit">Save changes</Button>
                <Button variant="ghost" onClick={reset}>Reset</Button>
              </div>
            </Form>
          )}
        </div>
      </div>
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
